1	"use client";
2	
3	import { useActionState, useEffect, useRef, useState } from "react";
4	import Link from "next/link";
5	import { purchaseDomain } from "@/lib/actions-domains";
6	import { DOMAIN_TERMS, domainTermPriceCents } from "@/lib/billing-terms";
7	import { fmtMoney } from "@/components/ui/primitives";
8	import type { DomainCheckResult } from "@/components/customer/DomainSearch";
9	
10	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
11	const PHONE_RE = /^\+\d{1,3}\.\d{4,14}$/;
12	// Same shape lib/domain-inbox-email.ts and lib/actions-email-hosting.ts's
13	// addMailbox() validate server-side — checked here only for immediate
14	// feedback; the server is the real gate.
15	const LOCAL_PART_RE = /^[a-z0-9]+(?:[._-][a-z0-9]+)*$/;
16	
17	const COUNTRIES: [string, string][] = [
18	  ["US", "United States"],
19	  ["CA", "Canada"],
20	  ["GB", "United Kingdom"],
21	  ["IE", "Ireland"],
22	  ["DE", "Germany"],
23	  ["FR", "France"],
24	  ["NL", "Netherlands"],
25	  ["BE", "Belgium"],
26	  ["ES", "Spain"],
27	  ["IT", "Italy"],
28	  ["PT", "Portugal"],
29	  ["SE", "Sweden"],
30	  ["NO", "Norway"],
31	  ["DK", "Denmark"],
32	  ["FI", "Finland"],
33	  ["PL", "Poland"],
34	  ["CH", "Switzerland"],
35	  ["AT", "Austria"],
36	  ["AU", "Australia"],
37	  ["NZ", "New Zealand"],
38	  ["JP", "Japan"],
39	  ["SG", "Singapore"],
40	  ["IN", "India"],
41	  ["BR", "Brazil"],
42	  ["MX", "Mexico"],
43	  ["ZA", "South Africa"],
44	];
45	
46	const BASE_STEPS = ["Domain", "Term", "Contact"] as const;
47	
48	type Contact = {
49	  firstName: string;
50	  lastName: string;
51	  address1: string;
52	  city: string;
53	  stateProvince: string;
54	  postalCode: string;
55	  country: string;
56	  phone: string;
57	  email: string;
58	};
59	
60	function Stepper({ step, steps }: { step: number; steps: readonly string[] }) {
61	  return (
62	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
63	      {steps.map((s, i) => (
64	        <div key={s} className="flex items-center gap-2">
65	          <span
66	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold transition-colors ${
67	              i === step
68	                ? "border-brand-400 bg-brand-500/20 text-brand-200"
69	                : i < step
70	                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
71	                  : "border-white/10 text-slate-500"
72	            }`}
73	          >
74	            {i < step ? "✓" : i + 1}
75	          </span>
76	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
77	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
78	        </div>
79	      ))}
80	    </div>
81	  );
82	}
83	
84	export function DomainRegisterWizard({
85	  initialDomain,
86	  initialCheck,
87	  defaultEmail,
88	  balanceCents,
89	  freeInboxPlan,
90	}: {
91	  initialDomain: string;
92	  initialCheck: DomainCheckResult | null;
93	  defaultEmail: string;
94	  balanceCents: number;
95	  /** The real "Free Domain Inbox" plan (lib/domain-inbox-email.ts), or null if
96	   *  it hasn't been seeded on this environment yet — the Email step only
97	   *  renders when this is present, so the wizard never claims a feature that
98	   *  isn't actually there. */
99	  freeInboxPlan: { mailboxes: number; storageGB: number } | null;
100	}) {
101	  const [state, action, pending] = useActionState(purchaseDomain, {} as { error?: string });
102	
103	  const STEPS = freeInboxPlan ? ([...BASE_STEPS, "Email", "Review"] as const) : ([...BASE_STEPS, "Review"] as const);
104	  const EMAIL_STEP = freeInboxPlan ? BASE_STEPS.length : -1;
105	  const REVIEW_STEP = STEPS.length - 1;
106	
107	  const [step, setStep] = useState(0);
108	  const [domain, setDomain] = useState(initialDomain);
109	  const [check, setCheck] = useState<DomainCheckResult | null>(initialCheck);
110	  const [checking, setChecking] = useState(false);
111	  const [checkError, setCheckError] = useState<string | null>(null);
112	  const [years, setYears] = useState(1);
113	  const [mailboxLocal, setMailboxLocal] = useState("");
114	
115	  const [contact, setContact] = useState<Contact>({
116	    firstName: "",
117	    lastName: "",
118	    address1: "",
119	    city: "",
120	    stateProvince: "",
121	    postalCode: "",
122	    country: "US",
123	    phone: "",
124	    email: defaultEmail,
125	  });
126	
127	  // Live search for changing the domain in step 1.
128	  const [q, setQ] = useState("");
129	  const [results, setResults] = useState<DomainCheckResult[] | null>(null);
130	  const [searching, setSearching] = useState(false);
131	  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
132	
133	  useEffect(() => {
134	    if (timer.current) clearTimeout(timer.current);
135	    const query = q.trim().toLowerCase();
136	    if (query.length < 2) {
137	      setResults(null);
138	      setSearching(false);
139	      return;
140	    }
141	    setSearching(true);
142	    timer.current = setTimeout(async () => {
143	      try {
144	        const res = await fetch(`/api/domains/check?q=${encodeURIComponent(query)}`, { cache: "no-store" });
145	        const json: { results?: DomainCheckResult[] } = await res.json();
146	        setResults(json.results ?? []);
147	      } catch {
148	        setResults([]);
149	      }
150	      setSearching(false);
151	    }, 400);
152	    return () => {
153	      if (timer.current) clearTimeout(timer.current);
154	    };
155	  }, [q]);
156	
157	  async function recheck(name: string) {
158	    setChecking(true);
159	    setCheckError(null);
160	    try {
161	      const res = await fetch(`/api/domains/check?q=${encodeURIComponent(name)}`, { cache: "no-store" });
162	      const json: { results?: DomainCheckResult[]; error?: string } = await res.json();
163	      const match = (json.results ?? []).find((r) => r.domain === name) ?? null;
164	      setCheck(match);
165	      if (json.error) setCheckError(json.error);
166	      else if (!match) setCheckError("Could not check that domain — try another.");
167	    } catch {
168	      setCheckError("Availability check failed — try again.");
169	      setCheck(null);
170	    }
171	    setChecking(false);
172	  }
173	
174	  function pickDomain(r: DomainCheckResult) {
175	    setDomain(r.domain);
176	    setCheck(r);
177	    setCheckError(null);
178	    setQ("");
179	    setResults(null);
180	  }
181	
182	  const priceCents = check?.priceCents ?? null;
183	  const domainOk =
184	    DOMAIN_RE.test(domain) && !!check && check.available && !check.premium && priceCents !== null;
185	  const totalCents = priceCents !== null ? domainTermPriceCents(priceCents, years) : 0;
186	  const afterCents = balanceCents - totalCents;
187	
188	  const contactValid =
189	    contact.firstName.trim().length > 0 &&
190	    contact.lastName.trim().length > 0 &&
191	    contact.address1.trim().length > 0 &&
192	    contact.city.trim().length > 0 &&
193	    contact.stateProvince.trim().length > 0 &&
194	    contact.postalCode.trim().length > 0 &&
195	    contact.country.length === 2 &&
196	    PHONE_RE.test(contact.phone) &&
197	    /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(contact.email);
198	
199	  const term = DOMAIN_TERMS.find((t) => t.years === years) ?? DOMAIN_TERMS[0];
200	  const mailboxLocalTrim = mailboxLocal.trim().toLowerCase();
201	  const mailboxLocalValid = mailboxLocalTrim.length === 0 || (LOCAL_PART_RE.test(mailboxLocalTrim) && mailboxLocalTrim.length <= 64);
202	  // The Email step is always passable without input — the free inbox is
203	  // reserved either way, an address is optional (see lib/domain-inbox-email.ts).
204	  const canContinue =
205	    (step === 0 && domainOk) ||
206	    step === 1 ||
207	    (step === 2 && contactValid) ||
208	    (EMAIL_STEP >= 0 && step === EMAIL_STEP && mailboxLocalValid) ||
209	    step === REVIEW_STEP;
210	  const isLast = step === REVIEW_STEP;
211	
212	  const set = (k: keyof Contact) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) =>
213	    setContact((c) => ({ ...c, [k]: e.target.value }));
214	
215	  return (
216	    <div className="grid gap-6 lg:grid-cols-[1fr_320px]">
217	      <form action={action} className="card">
218	        {/* hidden fields submitted to purchaseDomain */}
219	        <input type="hidden" name="domain" value={domain} />
220	        <input type="hidden" name="years" value={years} />
221	        <input type="hidden" name="firstName" value={contact.firstName} />
222	        <input type="hidden" name="lastName" value={contact.lastName} />
223	        <input type="hidden" name="address1" value={contact.address1} />
224	        <input type="hidden" name="city" value={contact.city} />
225	        <input type="hidden" name="stateProvince" value={contact.stateProvince} />
226	        <input type="hidden" name="postalCode" value={contact.postalCode} />
227	        <input type="hidden" name="country" value={contact.country} />
228	        <input type="hidden" name="phone" value={contact.phone} />
229	        <input type="hidden" name="email" value={contact.email} />
230	        <input type="hidden" name="mailboxLocalPart" value={mailboxLocalTrim} />
231	
232	        <Stepper step={step} steps={STEPS} />
233	
234	        {state?.error && (
235	          <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
236	            {state.error}
237	          </div>
238	        )}
239	
240	        {/* STEP 1 — DOMAIN */}
241	        {step === 0 && (
242	          <div>
243	            <h2 className="mb-1 font-semibold">Confirm your domain</h2>
244	            <p className="mb-4 text-sm text-slate-400">
245	              We&apos;ll re-check availability and pricing live before you commit.
246	            </p>
247	
248	            <div
249	              className={`rounded-xl border p-4 ${
250	                domainOk
251	                  ? "border-emerald-500/30 bg-emerald-500/[0.06]"
252	                  : check && (check.premium || !check.available)
253	                    ? "border-amber-500/30 bg-amber-500/[0.06]"
254	                    : "border-white/10 bg-white/[0.02]"
255	              }`}
256	            >
257	              <div className="flex flex-wrap items-center justify-between gap-3">
258	                <span className="font-mono text-base font-semibold">{domain || "no domain selected"}</span>
259	                {checking ? (
260	                  <span className="flex items-center gap-2 text-xs text-slate-400">
261	                    <span className="block h-3.5 w-3.5 animate-spin rounded-full border-2 border-slate-500 border-t-brand-400" />
262	                    checking…
263	                  </span>
264	                ) : domainOk && priceCents !== null ? (
265	                  <span className="text-sm font-semibold text-emerald-400">
266	                    available · {fmtMoney(priceCents)}
267	                    <span className="text-xs font-normal text-slate-400">/yr</span>
268	                  </span>
269	                ) : check?.premium ? (
270	                  <span className="text-sm font-semibold text-amber-300">premium — not supported</span>
271	                ) : check && !check.available ? (
272	                  <span className="text-sm font-semibold text-amber-300">taken</span>
273	                ) : (
274	                  <span className="text-sm text-slate-500">not checked</span>
275	                )}
276	              </div>
277	              {check?.renewCents != null && domainOk && (
278	                <p className="mt-2 text-xs text-slate-500">
279	                  Renews at {fmtMoney(check.renewCents)}/yr after the initial term.
280	                </p>
281	              )}
282	              <button
283	                type="button"
284	                onClick={() => domain && recheck(domain)}
285	                disabled={!DOMAIN_RE.test(domain) || checking}
286	                className="btn-ghost mt-2 px-0 text-xs"
287	              >
288	                ↻ Re-check availability
289	              </button>
290	            </div>
291	
292	            {checkError && <p className="mt-3 text-sm text-amber-300">{checkError}</p>}
293	
294	            <div className="mt-5">
295	              <label className="label">Search for a different domain</label>
296	              <div className="relative max-w-md">
297	                <input
298	                  className="input pr-10"
299	                  placeholder="another-name.com"
300	                  value={q}
301	                  onChange={(e) => setQ(e.target.value)}
302	                  autoComplete="off"
303	                  spellCheck={false}
304	                />
305	                <span className="absolute right-3.5 top-1/2 -translate-y-1/2 text-slate-500">
306	                  {searching ? (
307	                    <span className="block h-4 w-4 animate-spin rounded-full border-2 border-slate-500 border-t-brand-400" />
308	                  ) : (
309	                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
310	                      <circle cx="11" cy="11" r="7" />
311	                      <path d="m20 20-3.5-3.5" />
312	                    </svg>
313	                  )}
314	                </span>
315	              </div>
316	
317	              {results !== null && !searching && (
318	                <ul className="mt-3 max-w-md divide-y divide-white/[0.05] overflow-hidden rounded-xl border border-white/[0.06] bg-navy-900/60">
319	                  {results.length === 0 && (
320	                    <li className="px-4 py-3 text-sm text-slate-400">No supported TLDs match that search.</li>
321	                  )}
322	                  {results.map((r) => (
323	                    <li key={r.domain} className="flex items-center justify-between gap-3 px-4 py-2.5">
324	                      <span className="font-mono text-sm">{r.domain}</span>
325	                      {r.available && !r.premium && r.priceCents !== null ? (
326	                        <span className="flex items-center gap-3">
327	                          <span className="text-sm font-semibold text-emerald-400">{fmtMoney(r.priceCents)}</span>
328	                          <button
329	                            type="button"
330	                            onClick={() => pickDomain(r)}
331	                            className="btn-secondary px-3 py-1 text-xs"
332	                          >
333	                            Choose
334	                          </button>
335	                        </span>
336	                      ) : r.premium ? (
337	                        <span className="text-xs text-amber-300">premium</span>
338	                      ) : (
339	                        <span className="text-xs text-slate-500">taken</span>
340	                      )}
341	                    </li>
342	                  ))}
343	                </ul>
344	              )}
345	            </div>
346	          </div>
347	        )}
348	
349	        {/* STEP 2 — TERM */}
350	        {step === 1 && (
351	          <div>
352	            <h2 className="mb-1 font-semibold">Choose your registration term</h2>
353	            <p className="mb-4 text-sm text-slate-400">Commit longer, save more — WHOIS privacy is always included.</p>
354	            <div className="grid gap-3 sm:grid-cols-3">
355	              {DOMAIN_TERMS.map((t) => {
356	                const total = priceCents !== null ? domainTermPriceCents(priceCents, t.years) : 0;
357	                const perYear = t.years > 0 ? Math.round(total / t.years) : total;
358	                const on = years === t.years;
359	                return (
360	                  <button
361	                    type="button"
362	                    key={t.years}
363	                    onClick={() => setYears(t.years)}
364	                    className={`card relative p-4 text-left transition ${
365	                      on ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"
366	                    }`}
367	                  >
368	                    {t.discountPct > 0 && (
369	                      <span className="absolute right-2 top-2 rounded-full bg-emerald-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
370	                        −{t.discountPct}%
371	                      </span>
372	                    )}
373	                    <p className="text-sm font-semibold">{t.label}</p>
374	                    <p className="mt-1 text-xl font-bold">
375	                      {fmtMoney(perYear)}
376	                      <span className="text-xs font-normal text-slate-400">/yr</span>
377	                    </p>
378	                    <p className="mt-0.5 text-[11px] text-slate-500">
379	                      {fmtMoney(total)} total{t.discountPct > 0 ? ` · save ${t.discountPct}%` : ""}
380	                    </p>
381	                  </button>
382	                );
383	              })}
384	            </div>
385	            <div className="mt-5 flex items-center justify-between rounded-xl border border-white/10 bg-white/[0.02] px-4 py-3 text-sm">
386	              <span className="text-slate-400">
387	                {domain} · {term.label}
388	              </span>
389	              <span className="font-semibold">{fmtMoney(totalCents)} total</span>
390	            </div>
391	          </div>
392	        )}
393	
394	        {/* STEP 3 — CONTACT */}
395	        {step === 2 && (
396	          <div>
397	            <h2 className="mb-1 font-semibold">Registrant contact</h2>
398	            <p className="mb-4 text-sm text-slate-400">
399	              ICANN requires accurate contact details. These stay private — WHOIS privacy is included free.
400	            </p>
401	            <div className="grid gap-4 sm:grid-cols-2">
402	              <div>
403	                <label className="label">First name</label>
404	                <input className="input" value={contact.firstName} onChange={set("firstName")} maxLength={60} />
405	              </div>
406	              <div>
407	                <label className="label">Last name</label>
408	                <input className="input" value={contact.lastName} onChange={set("lastName")} maxLength={60} />
409	              </div>
410	              <div className="sm:col-span-2">
411	                <label className="label">Street address</label>
412	                <input
413	                  className="input"
414	                  value={contact.address1}
415	                  onChange={set("address1")}
416	                  maxLength={120}
417	                  placeholder="123 Main St"
418	                />
419	              </div>
420	              <div>
421	                <label className="label">City</label>
422	                <input className="input" value={contact.city} onChange={set("city")} maxLength={60} />
423	              </div>
424	              <div>
425	                <label className="label">State / Province</label>
426	                <input
427	                  className="input"
428	                  value={contact.stateProvince}
429	                  onChange={set("stateProvince")}
430	                  maxLength={60}
431	                />
432	              </div>
433	              <div>
434	                <label className="label">Postal code</label>
435	                <input className="input" value={contact.postalCode} onChange={set("postalCode")} maxLength={20} />
436	              </div>
437	              <div>
438	                <label className="label">Country</label>
439	                <select className="input" value={contact.country} onChange={set("country")}>
440	                  {COUNTRIES.map(([code, name]) => (
441	                    <option key={code} value={code}>
442	                      {name}
443	                    </option>
444	                  ))}
445	                </select>
446	              </div>
447	              <div>
448	                <label className="label">Phone</label>
449	                <input
450	                  className="input"
451	                  value={contact.phone}
452	                  onChange={set("phone")}
453	                  placeholder="+1.5551234567"
454	                />
455	                <p className={`mt-1 text-xs ${contact.phone && !PHONE_RE.test(contact.phone) ? "text-red-400" : "text-slate-500"}`}>
456	                  Format: +1.5551234567 (country code, dot, number)
457	                </p>
458	              </div>
459	              <div className="sm:col-span-2">
460	                <label className="label">Email</label>
461	                <input className="input" type="email" value={contact.email} onChange={set("email")} />
462	              </div>
463	            </div>
464	            {!contactValid && (
465	              <p className="mt-4 text-xs text-slate-500">Fill every field (and a valid phone/email) to continue.</p>
466	            )}
467	          </div>
468	        )}
469	
470	        {/* EMAIL STEP — free inbox included with the registration. Only renders
471	            when a real "Free Domain Inbox" plan is seeded (see
472	            lib/domain-inbox-email.ts) — the wizard never claims a feature that
473	            doesn't actually exist on this environment. */}
474	        {EMAIL_STEP >= 0 && step === EMAIL_STEP && freeInboxPlan && (
475	          <div>
476	            <h2 className="mb-1 font-semibold">Set up your free inbox</h2>
477	            <p className="mb-4 text-sm text-slate-400">
478	              Every domain registered with Nxeon includes a free email inbox —{" "}
479	              {freeInboxPlan.mailboxes} mailbox · {freeInboxPlan.storageGB} GB, no charge, for as
480	              long as the domain stays active. Pick an address now, or skip and add one later from{" "}
481	              <span className="font-medium text-slate-300">Email</span> in your dashboard.
482	            </p>
483	
484	            <label className="label">Mailbox address (optional)</label>
485	            <div className="flex max-w-md items-center">
486	              <input
487	                className="input rounded-r-none"
488	                value={mailboxLocal}
489	                onChange={(e) => setMailboxLocal(e.target.value)}
490	                placeholder="hello"
491	                autoCapitalize="none"
492	                autoCorrect="off"
493	                spellCheck={false}
494	              />
495	              <span className="whitespace-nowrap rounded-r-lg border border-l-0 border-white/10 bg-white/[0.03] px-3 py-2 text-sm text-slate-400">
496	                @{domain || "yourdomain.com"}
497	              </span>
498	            </div>
499	            {mailboxLocalTrim && !mailboxLocalValid && (
500	              <p className="mt-2 text-xs text-red-400">
501	                Use letters, numbers, and . _ - only (up to 64 characters).
502	              </p>
503	            )}
504	            {mailboxLocalTrim && mailboxLocalValid && (
505	              <p className="mt-2 text-xs text-emerald-400">
506	                {mailboxLocalTrim}@{domain} will be created as soon as the domain registers.
507	              </p>
508	            )}
509	            {!mailboxLocalTrim && (
510	              <p className="mt-2 text-xs text-slate-500">
511	                Leave this blank to skip for now — the free inbox stays reserved on this domain
512	                either way.
513	              </p>
514	            )}
515	          </div>
516	        )}
517	
518	        {/* STEP — REVIEW */}
519	        {step === REVIEW_STEP && (
520	          <div>
521	            <h2 className="mb-4 font-semibold">Review &amp; register</h2>
522	            <dl className="space-y-2.5 text-sm">
523	              <div className="flex items-center justify-between">
524	                <dt className="text-slate-400">Domain</dt>
525	                <dd className="font-mono">{domain}</dd>
526	              </div>
527	              <div className="flex items-center justify-between">
528	                <dt className="text-slate-400">Term</dt>
529	                <dd>
530	                  {term.label}
531	                  {term.discountPct > 0 && (
532	                    <span className="ml-2 rounded-full bg-emerald-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
533	                      −{term.discountPct}%
534	                    </span>
535	                  )}
536	                </dd>
537	              </div>
538	              <div className="flex items-center justify-between">
539	                <dt className="text-slate-400">Registrant</dt>
540	                <dd className="text-right">
541	                  {contact.firstName} {contact.lastName}
