29	/* ------------------------------------------------------------------ *
30	 * Idempotency helpers
31	 *
32	 * Layer 1 (cheap, in-process): a short-window duplicate-submit guard keyed on
33	 * user+domain. Catches the double-click / impatient-retry case immediately and
34	 * keeps two concurrent requests from both reaching the registrar. Best-effort
35	 * only — it does not survive a restart or span multiple app instances.
36	 *
37	 * Layer 2 (authoritative, in the DB): `Domain.name` is UNIQUE and the
38	 * charge+create runs in one `$transaction`, so a duplicate can never both take
39	 * money and create a second row. Renewal is guarded by an in-transaction expiry
40	 * re-check (charge and expiry advance together atomically).
41	 * ------------------------------------------------------------------ */
42	
43	const SUBMIT_GUARD_MS = 120_000;
44	const inFlightSubmits = new Map<string, number>();
45	
46	function beginSubmit(key: string): boolean {
47	  const now = Date.now();
48	  const heldUntil = inFlightSubmits.get(key);
49	  if (heldUntil !== undefined && heldUntil > now) return false;
50	  if (inFlightSubmits.size > 2000) {
51	    for (const [k, v] of inFlightSubmits) if (v <= now) inFlightSubmits.delete(k);
52	  }
53	  inFlightSubmits.set(key, now + SUBMIT_GUARD_MS);
54	  return true;
55	}
56	
57	function endSubmit(key: string): void {
58	  inFlightSubmits.delete(key);
59	}
