70	type RegistrationVerdict = { state: "registered" | "not-registered" | "unknown"; expires?: Date };
71	
72	/**
73	 * After a registrar call fails or times out we must NOT assume the registration
74	 * did not happen — name.com may well have taken the order. Ask the registrar
75	 * before touching the customer's money:
76	 *  - the domain is in our reseller account  -> registered (keep the charge)
77	 *  - the domain is still purchasable        -> not registered (safe to refund)
78	 *  - anything else / registrar unreachable  -> unknown (never auto-refund)
79	 */
80	async function verifyRegistration(domain: string): Promise<RegistrationVerdict> {
81	  try {
82	    const info = await domainInfo(domain);
83	    return { state: "registered", expires: info.expires };
84	  } catch {
85	    /* not in our account, or the API is unhappy — fall through to availability */
86	  }
87	  try {
88	    const [check] = await checkDomains([domain]);
89	    if (check?.available === true) return { state: "not-registered" };
90	  } catch {
91	    /* registrar unreachable */
92	  }
93	  return { state: "unknown" };
94	}
