96	export async function purchaseDomain(prev: any, formData: FormData): Promise<{ error?: string }> {
97	  // Spend path: registering a domain debits the wallet AND buys a non-refundable
98	  // asset from a registrar in the customer's name, with registrant contact details
99	  // taken from this form. `submitTransferIn` — the same product, the same money —
100	  // has carried this guard since it was written; registration and renewal never did.
101	  await assertNotImpersonating();
102	  const user = await requireUser();
103	  // Purchase gate: an unverified address means we cannot reach the person we
104	  // are about to charge. See lib/email-verification.ts.
105	  const unverified = await emailVerificationError(user);
106	  if (unverified) return { error: unverified };
107	  // Feature flag: domain registration can be switched off platform-wide.
108	  if (!(await getSettingBool("feature_domains", true))) {
109	    return { error: "Domain registration is currently unavailable." };
110	  }
111	  if (!registrarConfigured()) {
112	    return { error: "Domain registration is not configured yet (name.com API keys missing)." };
113	  }
114	  // Tag the order if the customer arrived via a partner deep link (?ref=kodely on
115	  // /dashboard/domains, captured into a cookie by PartnerSourceCapture). Read
116	  // synchronously here (unlike the VPS path, domain purchase is a same-request
117	  // wallet debit — no Stripe checkout/webhook race to round-trip through).
118	  const partnerSource = partnerSourceFromCookie(await cookies());
119	  const contactSchema = z.object({
120	    firstName: z.string().min(1).max(60),
121	    lastName: z.string().min(1).max(60),
122	    address1: z.string().min(1).max(120),
123	    city: z.string().min(1).max(60),
124	    stateProvince: z.string().min(1).max(60),
125	    postalCode: z.string().min(1).max(20),
126	    country: z.string().length(2),
127	    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
128	    email: z.string().email(),
129	  });
130	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
131	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
132	  const dTerm = domainTerm(Number(formData.get("years") ?? 1));
133	  // Free Domain Inbox — the mailbox local-part the customer optionally chose
134	  // during registration (components/customer/DomainRegisterWizard.tsx's Email
135	  // step). Empty is valid: the inbox is still reserved, just mailbox-less
136	  // until they add one from /dashboard/email. See lib/domain-inbox-email.ts.
137	  const mailboxLocalPart = String(formData.get("mailboxLocalPart") ?? "").trim().toLowerCase() || null;
138	
139	  const contactParsed = contactSchema.safeParse({
140	    firstName: formData.get("firstName"),
141	    lastName: formData.get("lastName"),
142	    address1: formData.get("address1"),
143	    city: formData.get("city"),
144	    stateProvince: formData.get("stateProvince"),
145	    postalCode: formData.get("postalCode"),
146	    country: String(formData.get("country") ?? "").toUpperCase(),
147	    phone: formData.get("phone"),
148	    email: formData.get("email"),
149	  });
150	  if (!contactParsed.success) {
151	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
152	  }
153	
154	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
155	  const guardKey = `register:${user.id}:${domain}`;
156	  if (!beginSubmit(guardKey)) {
157	    return { error: "That registration is already being processed — give it a moment before retrying." };
158	  }
159	
160	  try {
161	    const existing = await db.domain.findUnique({ where: { name: domain } });
162	    if (existing) {
163	      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
164	      if (existing.status === "PENDING") {
165	        return { error: "You already have a registration in progress for this domain." };
166	      }
167	      return { error: `You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).` };
168	    }
169	
170	    // Live availability + retail(markup) & cost prices from name.com
171	    let priceCents: number; // retail per year (customer)
172	    let costCents: number; // registrar cost per year (us)
173	    try {
174	      const [check] = await checkDomains([domain]);
175	      if (!check) return { error: "Could not check availability. Try again." };
176	      if (!check.available) return { error: "Domain is not available." };
177	      if (check.premium) return { error: "Premium domains are not supported yet." };
178	      if (check.priceCents === null || check.costCents === null) return { error: "No price available for this TLD." };
179	      priceCents = check.priceCents;
180	      costCents = check.costCents;
181	    } catch (e: any) {
182	      return { error: String(e?.message ?? e).slice(0, 200) };
183	    }
184	
185	    const totalCents = domainTermPriceCents(priceCents, dTerm.years); // customer pays (retail, term-discounted)
186	    const registrarCostCents = costCents * dTerm.years; // we pay name.com the true cost
187	    if (user.balanceCents < totalCents) {
188	      return { error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}.` };
189	    }
190	
191	    let record;
192	    try {
193	      record = await db.$transaction(async (tx) => {
194	        // Re-check inside the transaction: the availability round-trip above is
195	        // slow enough for a second submit to slip in. `Domain.name` is UNIQUE, so
196	        // even if this read misses, the create below rolls the whole debit back.
197	        const dupe = await tx.domain.findUnique({ where: { name: domain }, select: { id: true } });
198	        if (dupe) throw new DuplicateDomainError();
199	        await debitWallet(tx, user.id, totalCents);
200	        await tx.walletTransaction.create({
201	          data: { userId: user.id, amountCents: -totalCents, description: `Domain registration: ${domain} (${dTerm.label})` },
202	        });
203	        return tx.domain.create({
204	          data: {
205	            name: domain,
206	            userId: user.id,
207	            priceCents,
208	            costCents,
209	            termYears: dTerm.years,
210	            status: "PENDING",
211	            registrar: "name.com",
212	            partnerSource: partnerSource ?? null,
213	          },
214	        });
215	      });
216	    } catch (e) {
217	      if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
218	      if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
219	        return { error: "This domain is already being registered — you have not been charged twice." };
220	      }
221	      throw e;
222	    }
223	
224	    try {
225	      const { expiresAt } = await registerDomain(domain, dTerm.years, contactParsed.data as RegistrantContact, registrarCostCents);
226	      const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
227	      await db.domain.update({
228	        where: { id: record.id },
229	        data: {
230	          status: "ACTIVE",
231	          registeredAt: new Date(),
232	          expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
233	        },
234	      });
235	      await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: `${domain} ${dTerm.years}yr` } });
236	      await db.notification.create({
237	        data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
238	      });
239	      // Tell the partner (best-effort, never blocks the order) — only for orders
240	      // tagged via a partner deep link. Most domain registrations are direct Nxeon
241	      // customers and must never be forwarded to a partner's webhook.
242	      if (partnerSource === "kodely") {
243	        await notifyPartner("domain.registered", { userId: user.id, domain, expiresAt: info.expires ?? null });
244	      }
245	      // Every domain registered through Nxeon includes a free inbox — see
246	      // lib/domain-inbox-email.ts. Best-effort: never lets a mailbox hiccup
247	      // undo a domain purchase that already succeeded.
248	      await setupDomainInboxEmail({
249	        userId: user.id,
250	        domainName: domain,
251	        expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
252	        mailboxLocalPart,
253	      });
254	    } catch (e: any) {
255	      const reason = String(e?.message ?? e).slice(0, 400);
256	      // NEVER refund blind: a timeout/5xx often means the order DID go through.
257	      const verdict = await verifyRegistration(domain);
258	
259	      if (verdict.state === "registered") {
260	        // The registration exists — keep the charge and finish the record.
261	        await db.domain.update({
262	          where: { id: record.id },
263	          data: {
264	            status: "ACTIVE",
265	            registeredAt: new Date(),
266	            expiresAt: verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
267	            error: `Recovered after registrar error: ${reason}`.slice(0, 500),
268	          },
269	        });
270	        await db.auditLog.create({
271	          data: { userId: user.id, action: "domain.register.recovered", detail: `${domain}: ${reason}`.slice(0, 500) },
272	        });
273	        await db.notification.create({
274	          data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
275	        });
276	        // Recovered-but-registered still counts as a successful registration —
277	        // it gets the same free inbox the happy path does.
278	        await setupDomainInboxEmail({
279	          userId: user.id,
280	          domainName: domain,
281	          expiresAt: verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
282	          mailboxLocalPart,
283	        });
284	        // `?new=1` triggers the one-time "domain registered" success banner +
285	        // hosting/VPS upsell on the domain page (app/dashboard/domains/[id]/page.tsx).
286	        redirect(`/dashboard/domains/${record.id}?new=1`);
287	      }
288	
289	      if (verdict.state === "not-registered") {
290	        // Confirmed still available at the registrar — refunding is safe.
291	        await db.$transaction([
292	          db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
293	          db.walletTransaction.create({
294	            data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
295	          }),
296	          db.domain.update({
297	            where: { id: record.id },
298	            data: { status: "FAILED", error: reason.slice(0, 500) },
299	          }),
300	        ]);
301	        return { error: `Registration failed: ${reason.slice(0, 200)} (you were refunded).` };
302	      }
303	
304	      // Unknown: leave PENDING and charged, flag for manual review. Refunding
305	      // here risks giving away a domain we actually paid the registrar for.
306	      await db.domain.update({
307	        where: { id: record.id },
308	        data: { status: "PENDING", error: `NEEDS REVIEW — registrar status unconfirmed: ${reason}`.slice(0, 500) },
309	      });
310	      await db.auditLog.create({
311	        data: { userId: user.id, action: "domain.register.needs_review", detail: `${domain}: ${reason}`.slice(0, 500) },
312	      });
313	      await db.notification.create({
314	        data: {
315	          userId: user.id,
316	          title: `Domain ${domain} needs review`,
317	          body: "We could not confirm the registration with the registrar. Our team is checking it — no duplicate charge will be made.",
318	          href: `/dashboard/domains/${record.id}`,
319	        },
320	      });
321	      return {
322	        error:
323	          `We could not confirm ${domain} with the registrar (${reason.slice(0, 120)}). ` +
324	          `It is marked for review — do not retry, you will not be charged twice.`,
325	      };
326	    }
327	    redirect(`/dashboard/domains/${record.id}?new=1`);
328	  } finally {
329	    endSubmit(guardKey);
330	  }
331	}
