333	/** A renewal already landed if the registrar expiry runs ~a month past ours. */
334	const RENEW_SLACK_MS = 30 * 86400_000;
335	
336	export async function renewDomainAction(domainId: string): Promise<{ error?: string }> {
337	  // Spend path: a manual renewal debits the wallet and spends at the registrar.
338	  // See purchaseDomain above.
339	  await assertNotImpersonating();
340	  const user = await requireUser();
341	  // Purchase gate: a MANUAL renewal is a fresh spend decision. Automatic domain
342	  // renewal runs in the worker and does not come through here, so no existing
343	  // domain can lapse because of this check.
344	  const unverifiedRenew = await emailVerificationError(user);
345	  if (unverifiedRenew) return { error: unverifiedRenew };
346	  const domain = await db.domain.findUnique({ where: { id: domainId } });
347	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
348	  if (domain.status === "PENDING") return { error: "This domain's registration is still being confirmed." };
349	  if (domain.status === "FAILED") return { error: "This domain is not registered." };
350	
351	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
352	  const guardKey = `renew:${domain.userId}:${domain.name}`;
353	  if (!beginSubmit(guardKey)) {
354	    return { error: "A renewal for this domain is already in progress." };
355	  }
356	
357	  try {
358	    const dTerm = domainTerm(domain.termYears);
359	    const renewCents = domainTermPriceCents(domain.priceCents, dTerm.years);
360	    const owner = await db.user.findUnique({ where: { id: domain.userId } });
361	    if (!owner || owner.balanceCents < renewCents) return { error: "Insufficient balance." };
362	
363	    const dbExpiry = domain.expiresAt ?? null;
364	
365	    // Idempotency: charge and expiry advance together in one transaction below,
366	    // so if the registrar expiry is already ahead of ours a previous attempt
367	    // renewed but never got charged/recorded. Adopt that renewal instead of
368	    // buying a second year.
369	    let registrarExpiry: Date | undefined;
370	    try {
371	      registrarExpiry = (await domainInfo(domain.name)).expires;
372	    } catch {
373	      /* non-fatal: fall through to a normal renew */
374	    }
375	    const alreadyRenewed =
376	      !!registrarExpiry && !!dbExpiry && registrarExpiry.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS;
377	
378	    if (!alreadyRenewed) {
379	      try {
380	        await renewDomain(domain.name, dTerm.years, (domain.costCents || domain.priceCents) * dTerm.years);
381	      } catch (e: any) {
382	        // The registrar call is the FIRST thing that happens, before any debit,
383	        // so "you have not been charged" is a fact here, not a hope — and saying
384	        // it stops a customer retrying a renewal they think half-succeeded.
385	        return {
386	          error:
387	            `The registrar refused to renew ${domain.name}: ${String(e?.message ?? e).slice(0, 200)}. ` +
388	            `Nothing has been charged. Wait a few minutes and try again; if it keeps failing, contact support with this message.`,
389	        };
390	      }
391	      registrarExpiry = await domainInfo(domain.name)
392	        .then((i) => i.expires)
393	        .catch(() => undefined);
394	    }
395	
396	    const targetExpiry =
397	      registrarExpiry ?? new Date((dbExpiry ?? new Date()).getTime() + dTerm.years * 365 * 86400_000);
398	
399	    try {
400	      const charged = await db.$transaction(async (tx) => {
401	        // Re-read under the transaction: if a concurrent request already advanced
402	        // the expiry it also already took the money — do not charge again.
403	        const fresh = await tx.domain.findUnique({ where: { id: domainId }, select: { expiresAt: true } });
404	        if (dbExpiry && fresh?.expiresAt && fresh.expiresAt.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS) {
405	          return false;
406	        }
407	        await debitWallet(tx, domain.userId, renewCents);
408	        await tx.walletTransaction.create({
409	          data: { userId: domain.userId, amountCents: -renewCents, description: `Domain renewal: ${domain.name} (${dTerm.label})` },
410	        });
411	        await tx.domain.update({
412	          where: { id: domainId },
413	          data: { expiresAt: targetExpiry, status: "ACTIVE" },
414	        });
415	        return true;
416	      });
417	      if (!charged) {
418	        revalidatePath(`/dashboard/domains/${domainId}`);
419	        return {};
420	      }
421	    } catch (e) {
422	      if (e instanceof InsufficientBalanceError) {
423	        // The registrar renewal already succeeded — flag the uncollected charge
424	        // instead of silently swallowing it.
425	        await db.auditLog
426	          .create({
427	            data: {
428	              userId: domain.userId,
429	              action: "domain.renew.uncharged",
430	              detail: `${domain.name}: renewed at registrar but wallet debit of ${renewCents}c failed`,
431	            },
432	          })
433	          .catch(() => {});
434	        return { error: "Insufficient balance." };
435	      }
436	      throw e;
437	    }
438	    revalidatePath(`/dashboard/domains/${domainId}`);
439	    return {};
440	  } finally {
441	    endSubmit(guardKey);
442	  }
443	}
