469	    ctx = await ownedDomain(domainId);
470	  } catch (e: any) {
471	    return { error: e.message };
472	  }
473	  const parsed = z
474	    .object({
475	      name: z.string().max(120).default(""),
476	      type: z.enum(RECORD_TYPES),
477	      address: z.string().min(1).max(500),
478	      ttl: z.coerce.number().int().min(60).max(86400).default(300),
479	      mxPref: z.coerce.number().int().min(0).max(65535).optional(),
