483	      type: formData.get("type"),
484	      address: formData.get("address"),
485	      ttl: formData.get("ttl") || 300,
486	      mxPref: formData.get("mxPref") || undefined,
487	    });
488	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid record." };
489	
490	  // "@" or blank => apex (name.com uses empty host for apex)
491	  const host = ["@", ""].includes(parsed.data.name.trim()) ? "" : parsed.data.name.trim();
492	  try {
493	    await addRecord(ctx.domain.name, {
494	      host,
495	      type: parsed.data.type,
496	      answer: parsed.data.address,
497	      ttl: parsed.data.ttl,
498	      priority: parsed.data.type === "MX" || parsed.data.type === "SRV" ? parsed.data.mxPref ?? 10 : undefined,
499	    });
500	  } catch (e: any) {
501	    // Say what the provider said AND what to do about it. A bare registrar
502	    // string ("422 Unprocessable Entity") tells a customer nothing they can act
503	    // on; this product's standard is that an error explains both halves.
504	    return {
505	      error:
506	        `Your DNS provider refused this record: ${String(e?.message ?? e).slice(0, 200)}. ` +
507	        `Check the value matches the record type (an A record needs an IPv4 address, a CNAME needs a hostname), ` +
508	        `then try again. Nothing was changed.`,
509	    };
510	  }
