542	/**
543	 * One-click: point apex + www at the platform's public IP.
544	 *
545	 * ADD BEFORE DELETE, per host. This used to delete every apex/www A record and
546	 * only then add the replacements — so a registrar hiccup, a rate limit or a
547	 * network blip in between took the domain DARK and left it that way, with an
548	 * error message that did not say the old records were already gone. That is the
549	 * "six domains dark while the run scored 4/4" failure shape: destructive work
550	 * done first, on the assumption the constructive half cannot fail.
551	 *
552	 * The new order is also idempotent — an A record already pointing at `ip` is
553	 * kept rather than churned — so clicking twice is free, and a half-finished run
554	 * can simply be retried.
555	 */
556	export async function pointDomainAtServer(domainId: string): Promise<{ error?: string }> {
557	  let ctx;
558	  try {
559	    ctx = await ownedDomain(domainId);
560	  } catch (e: any) {
561	    return { error: e.message };
562	  }
563	  const ip = process.env.PUBLIC_IP;
564	  if (!ip) {
565	    return {
566	      error:
567	        "This platform doesn't have a public IP configured, so there is nothing to point the domain at. " +
568	        "Contact support — this is a platform configuration problem, not something you can fix from here.",
569	    };
570	  }
571	
572	  const done: string[] = [];
573	  try {
574	    const recs = await listRecords(ctx.domain.name);
575	    for (const host of ["", "www"]) {
576	      const label = host === "" ? ctx.domain.name : `www.${ctx.domain.name}`;
577	      const existing = recs.filter((r) => r.host === host && r.type === "A");
578	      const keep = existing.find((r) => r.answer === ip);
579	      // Constructive half FIRST: the name resolves somewhere at every instant.
580	      if (!keep) await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
581	      // Only now retire the records that point elsewhere.
582	      for (const r of existing) {
583	        if (keep && r.id === keep.id) continue;
584	        await deleteRecord(ctx.domain.name, r.id);
585	      }
586	      done.push(label);
587	    }
588	  } catch (e: any) {
589	    const reason = String(e?.message ?? e).slice(0, 200);
590	    return {
591	      error:
592	        `Your DNS provider rejected part of this change (${reason}). ` +
593	        (done.length > 0
594	          ? `${done.join(" and ")} ${done.length === 1 ? "was" : "were"} pointed at ${ip} and ${done.length === 1 ? "is" : "are"} live; the rest was not changed. `
595	          : "Nothing was changed and your existing records are untouched. ") +
596	        `Wait a minute and click Point at server again — it is safe to repeat.`,
597	    };
598	  }
599	  revalidatePath(`/dashboard/domains/${domainId}`);
600	  return {};
601	}
