516	/**
517	 * Credit the wallet for a paid PayPal/Coinbase Commerce session — the non-Stripe
518	 * analogue of `creditCheckoutSession` (lib/stripe.ts). Deliberately a SEPARATE,
519	 * smaller function rather than a call into that one, for two reasons:
520	 *
521	 *  1. Honesty of the ledger. `creditCheckoutSession` hard-codes the wallet-
522	 *     transaction description as `Stripe payment (${session.id})`. Reusing it for
523	 *     PayPal/Coinbase would label a customer's PayPal or crypto payment as a
524	 *     "Stripe payment" in their own billing history AND in the admin refund
525	 *     tool's ledger search (`lib/actions-admin-billing.ts`'s `description:
526	 *     {contains: "Stripe payment (cs_"}` — that regex's `cs_` prefix requirement
527	 *     means a synthetic `paypal:`/`coinbase:` id would never match it anyway, so
528	 *     nothing is UNSAFE, but the label would still be a plain false statement.
529	 *  2. Every external-payment session reaching this function was created by our
530	 *     own `lib/actions-payment-providers.ts` order/charge-creation actions, which
531	 *     never create one without purchase metadata (order/gameOrder/hostOrder/
532	 *     emailOrder) — there is no "top up your wallet with PayPal/crypto" product.
533	 *     So unlike `creditCheckoutSession`, there is no top-up invoice branch here;
534	 *     `isPurchaseLegSession` is asserted rather than branched on, and a session
535	 *     that somehow fails it is refused loudly rather than silently treated as a
536	 *     top-up (exactly the "unrecognised metadata → top-up" bug `packMetadata`'s
537	 *     doc comment and the `unreadable` classification exist to end — the failure
538	 *     mode this function must never reintroduce from a different code path).
539	 *
540	 * Idempotent the same way: UNIQUE(stripeSessionId) on `WalletTransaction`, so a
541	 * client-driven capture racing the provider's webhook is safe — P2002 means
542	 * someone else already credited this exact session id.
543	 */
544	async function creditExternalPayment(
545	  session: Stripe.Checkout.Session,
546	  provider: Exclude<PaymentProvider, "stripe">,
547	): Promise<boolean> {
548	  const userId = session.metadata?.nxeonUserId;
549	  const cents = session.amount_total ?? 0;
550	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
551	
552	  if (!isPurchaseLegSession(session.metadata)) {
553	    throw new Error(
554	      `${provider} payment ${session.id} carries no recognised purchase metadata — refusing to treat unrecognised money as a top-up`,
555	    );
556	  }
557	
558	  const label = provider === "paypal" ? "PayPal" : "Coinbase Commerce";
559	  try {
560	    await db.$transaction([
561	      db.walletTransaction.create({
562	        data: {
563	          userId,
564	          amountCents: cents,
565	          description: `${label} payment (${session.id})`,
566	          stripeSessionId: session.id,
567	        },
568	      }),
569	      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
570	      db.notification.create({
571	        data: {
572	          userId,
573	          title: `Payment of $${(cents / 100).toFixed(2)} received`,
574	          href: "/dashboard/billing",
575	        },
576	      }),
577	    ]);
578	  } catch (e) {
579	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
580	    throw e;
581	  }
582	  // Best-effort side effects, same as creditCheckoutSession — never allowed to
583	  // turn a completed credit into a reported failure.
584	  try {
585	    const { maybeRewardReferral } = await import("./actions-growth");
586	    await maybeRewardReferral(userId);
587	  } catch {
588	    /* best-effort */
589	  }
590	  // No generic "Payment received" receipt here: every session this function
591	  // credits is a purchase leg (see this function's doc comment — there is no
592	  // "top up with PayPal/crypto" product), so the order this money is funding
593	  // sends its own specific, itemised invoice_new email moments later. Sending
594	  // both meant a generic, invoice-less "your Nxeon order" receipt landed right
595	  // before the real invoice on every PayPal/Coinbase purchase — the exact
596	  // "this email is weak" duplication already removed from the Stripe path in
597	  // creditCheckoutSession.
598	  return true;
599	}
