601	export type ExternalPaymentInput = {
602	  provider: Exclude<PaymentProvider, "stripe">;
603	  /** PayPal's order id, or Coinbase Commerce's charge code — the provider's own reference. */
604	  externalId: string;
605	  /** The `PendingExternalPayment` row id created when the order/charge was opened
606	   *  (lib/actions-payment-providers.ts) — the ONE place the full order metadata lives. */
607	  pendingId: string;
608	  base?: string;
609	};
610	
611	/**
612	 * Fulfil a PAID PayPal order or Coinbase Commerce charge through the EXACT SAME
613	 * `runFulfilment` dispatch Stripe's `fulfilCheckoutSession` uses — the seam this
614	 * whole module exists to provide. Builds a SYNTHETIC `Stripe.Checkout.Session`-
615	 * shaped object from the `PendingExternalPayment` row (same nxeon* metadata keys,
616	 * `payment_status: "paid"`, the row's own server-computed `amountCents`) and hands
617	 * it to `runFulfilment` with `provider` set so the two Stripe-only steps above are
618	 * skipped. There is exactly ONE dispatch function in this codebase; this is how a
619	 * second payment rail reaches it without a second copy of the claim/settle/
620	 * provision/notify logic.
621	 *
622	 * Callers: the PayPal capture server action (client-driven, like Stripe's confirm
623	 * redirect) AND the PayPal webhook (the reliable backstop) — the SAME
624	 * confirm/webhook race Stripe already runs safely, because the claim below is the
625	 * same `FulfilledSession` UNIQUE(stripeSessionId) index, just keyed
626	 * `"paypal:<orderId>"` instead of a Stripe session id. Coinbase Commerce has no
627	 * client-driven capture step (crypto confirmation only ever arrives by webhook),
628	 * so its webhook is the only caller — still idempotent on its own if Coinbase ever
629	 * redelivers the event.
630	 *
631	 * THROWS if the `PendingExternalPayment` row cannot be found or its stored
632	 * metadata is not valid JSON — the same "throw rather than silently misclassify"
633	 * discipline `retrieveCheckoutSession` and `fulfilCheckoutSession` already apply
634	 * to a Stripe read failure. A row that cannot be trusted must never fall through
635	 * to the top-up branch.
636	 */
637	export async function fulfilExternalPayment(input: ExternalPaymentInput): Promise<FulfilResult> {
638	  const row = await db.pendingExternalPayment.findUnique({ where: { id: input.pendingId } });
639	  if (!row) {
640	    throw new Error(`No PendingExternalPayment row for id ${input.pendingId} (${input.provider} ${input.externalId})`);
641	  }
642	  if (row.provider !== input.provider) {
643	    throw new Error(
644	      `PendingExternalPayment ${input.pendingId} provider mismatch: expected ${input.provider}, stored ${row.provider}`,
645	    );
646	  }
647	
648	  let metadata: Record<string, string>;
649	  try {
650	    const parsed = JSON.parse(row.metadata);
651	    if (!parsed || typeof parsed !== "object") throw new Error("not an object");
652	    metadata = parsed as Record<string, string>;
653	  } catch {
654	    throw new Error(`PendingExternalPayment ${input.pendingId} metadata is not readable JSON`);
655	  }
656	
657	  // The provider-qualified id IS the FulfilledSession/WalletTransaction claim key —
658	  // "paypal:5O190127TN364715T" can never collide with a real Stripe `cs_...` id or
659	  // with the other provider's charge codes.
660	  const sessionId = `${input.provider}:${input.externalId}`;
661	  const synthetic = {
662	    id: sessionId,
663	    metadata,
664	    payment_status: "paid",
665	    amount_total: row.amountCents,
666	    currency: row.currency,
667	    customer: null,
668	    payment_intent: null,
669	  } as unknown as Stripe.Checkout.Session;
670	
671	  const purpose = classifyCheckoutSession(synthetic);
672	
673	  try {
674	    const result = await runFulfilment(synthetic, purpose, input.base ?? "", input.provider);
675	    await db.pendingExternalPayment
676	      .update({ where: { id: row.id }, data: { status: "PAID", providerRef: input.externalId } })
677	      .catch(() => {});
678	    return result;
679	  } catch (e) {
680	    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { status: "FAILED" } }).catch(() => {});
681	    throw e;
682	  }
683	}
