312	function CardAndWalletsBlock({
313	  selected,
314	  onSelectCard,
315	  saveCard,
316	  onToggleSaveCard,
317	  totalDueCents,
318	}: {
319	  selected: Method;
320	  onSelectCard: () => void;
321	  saveCard: boolean;
322	  onToggleSaveCard: (v: boolean) => void;
323	  totalDueCents: number;
324	}) {
325	  // useCheckoutElements() (not the deprecated useCheckout()) returns a
326	  // discriminated union — {type:"loading"} while the Elements SDK is still
327	  // initializing, {type:"error"} if it failed, {type:"success", checkout}
328	  // once ready. `checkoutActions` is that inner `checkout` object, undefined
329	  // until "success" — every confirm() call below is guarded on it existing,
330	  // so a click during the loading window can't throw.
331	  const checkoutState = useCheckoutElements();
332	  const checkoutActions = checkoutState.type === "success" ? checkoutState.checkout : undefined;
333	  const [confirming, setConfirming] = useState(false);
334	  const [error, setError] = useState<string | null>(null);
335	  const [name, setName] = useState("");
336	  const [expressPayAvailable, setExpressPayAvailable] = useState(false);
337	
338	  async function payWithCard() {
339	    if (!checkoutActions) return;
340	    setError(null);
341	    setConfirming(true);
342	    try {
343	      const result = await checkoutActions.confirm({ savePaymentMethod: saveCard });
344	      if (result.type === "error") setError(result.error.message ?? "Your card was declined. Please try another payment method.");
345	      // On success Stripe navigates the browser to the session's return_url
346	      // (/api/stripe/confirm) — the SAME route that fulfils every other Stripe
347	      // payment on this platform. Nothing else to do here.
348	    } catch {
349	      setError("Something went wrong confirming your payment. Please try again.");
350	    } finally {
351	      setConfirming(false);
352	    }
353	  }
354	
355	  return (
356	    <>
357	      <MethodRow
358	        id="card"
359	        selected={selected === "card"}
360	        onSelect={onSelectCard}
361	        icon={<CardIcon />}
362	        title="Credit / Debit Card"
