374	                  fields: { billingDetails: { name: "never" } },
375	                  paymentMethodOrder: ["card"],
376	                }}
377	              />
378	            </div>
379	          </div>
380	          <div>
381	            <label className="mb-1.5 block text-xs font-medium text-slate-400">Cardholder name</label>
382	            <input
383	              type="text"
384	              value={name}
385	              onChange={(e) => setName(e.target.value)}
386	              placeholder="Name on card"
387	              className="w-full rounded-lg border border-white/[0.08] bg-white/[0.02] px-3 py-2 text-sm text-slate-200 placeholder:text-slate-600 focus:border-brand-400/50 focus:outline-none"
388	            />
389	          </div>
390	          <label className="flex items-start gap-2.5 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
391	            <input type="checkbox" checked={saveCard} disabled className="mt-0.5 h-3.5 w-3.5 accent-brand-500" onChange={(e) => onToggleSaveCard(e.target.checked)} />
392	            <span className="text-xs text-slate-400">
393	              <span className="font-medium text-slate-300">Save card for faster checkout</span>
394	              <br />
395	              Nxeon plans renew automatically, so your card is always saved securely with Stripe for your next billing cycle — this isn&apos;t optional for a subscription product, which is why the box is checked.
396	            </span>
397	          </label>
398	          {error && <p className="rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 text-xs text-red-300">{error}</p>}
399	          <button
400	            type="button"
401	            onClick={payWithCard}
402	            disabled={confirming || !checkoutActions?.canConfirm}
403	            className="btn-deploy w-full py-3 text-sm"
404	          >
405	            <LockIcon className="h-4 w-4" />
406	            {confirming ? "Processing…" : `Pay Securely ${money(totalDueCents)}`}
407	            {!confirming && <span className="dep-arrow">→</span>}
408	          </button>
409	        </div>
410	      </MethodRow>
411	
412	      {/*
413	        ONE ExpressCheckoutElement, always mounted, showing whichever wallets
414	        the browser/device actually supports (Stripe renders them side by
415	        side itself). This used to be TWO separate elements — one per wallet,
416	        each shown only when its own MethodRow was the "selected" radio
417	        option — which looked static (nothing to click until you clicked the
418	        row first) and, worse, having both mount at once (needed to fix the
419	        static look) throws Stripe's own "cannot create multiple instances of
420	        the Express Checkout Element" error. A single instance covering both
421	        wallets is Stripe's actual supported shape for this. Hidden entirely
422	        (via onReady's availablePaymentMethods) when NEITHER wallet is
423	        available on this browser/device/card.
424	      */}
425	      {/* Always mounted (never conditionally unmounted) so onReady gets a
426	          chance to fire at all — only its VISIBILITY is gated on the result,
427	          via a CSS class rather than removing it from the tree. */}
428	      <div className={expressPayAvailable ? "rounded-xl border border-white/[0.07] bg-white/[0.02] p-4" : "hidden"}>
429	          <p className="mb-3 text-xs font-medium text-slate-400">Express checkout</p>
430	          <ExpressCheckoutElement
431	            options={{
432	              // The /checkout subpath's ExpressCheckoutElementOptions requires
433	              // every key present (unlike the main package's), even though
434	              // Stripe treats undefined the same as omitted for each of these.
435	              buttonHeight: undefined,
436	              buttonTheme: undefined,
437	              buttonType: undefined,
438	              layout: undefined,
439	              paymentMethodOrder: undefined,
440	              paymentMethods: { googlePay: "auto", applePay: "auto", link: "never", paypal: "never", amazonPay: "never" },
441	            }}
442	            onReady={(e) =>
443	              setExpressPayAvailable(!!(e.availablePaymentMethods?.googlePay || e.availablePaymentMethods?.applePay))
444	            }
445	            // The Custom Checkout version of this element does not expose
446	            // onClick (Stripe's SDK owns opening the OS payment sheet
447	            // entirely).
448	            onConfirm={async (event) => {
449	              if (!checkoutActions) return;
450	              setError(null);
451	              const result = await checkoutActions.confirm({ expressCheckoutConfirmEvent: event });
452	              if (result.type === "error") setError(result.error.message ?? "Payment failed.");
453	            }}
454	          />
455	      </div>
456	    </>
457	  );
458	}
