473	  // Ask for a Stripe session as soon as this step is visible, so Card/Google
474	  // Pay/Apple Pay are ready to accept input immediately (matching the mockup)
475	  // instead of only appearing after a click. `stripe.status` is entirely
476	  // PARENT-controlled: the wizard flips it away from "idle" the instant it acts
477	  // on this call, and flips it BACK to "idle" itself if the price changes after
478	  // a session was already created (a coupon applied, the wallet toggle changed)
479	  // — so this effect re-requests a fresh session exactly when the parent decides
480	  // the old one is stale, with no local "only once" state of its own to fight it.
481	  useEffect(() => {
482	    if (stripe.status === "idle") onRequestStripeSession();
483	  }, [stripe.status, onRequestStripeSession]);
