272	/**
273	 * Pick the least-committed enabled node (RAM headroom), while steering AWAY from
274	 * a node this order would push to/past the CRITICAL capacity threshold when
275	 * another node has room. Falls back to primary (any node) when every candidate is
276	 * already critical — the scheduler never REFUSES an order for a capacity warning
277	 * (that's the node-capacity alert's job, lib/node-capacity.ts); it only prefers a
278	 * roomier node when one exists. DB-only so order placement never blocks on a
279	 * Proxmox round trip.
280	 */
281	async function scheduleNode(planRamMB: number) {
282	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
283	  if (nodes.length === 0) return null;
284	  const loads = await Promise.all(
285	    nodes.map(async (n) => {
286	      const agg = await db.server.findMany({
287	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
288	        select: { plan: { select: { ramMB: true } } },
289	      });
290	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
291	      // Commitment AFTER this VM lands — that's what decides whether placing here
292	      // tips the node critical.
293	      const projectedPct = n.capacityRamMB > 0 ? ((used + planRamMB) / n.capacityRamMB) * 100 : 100;
294	      return { node: n, free: n.capacityRamMB - used, projectedPct };
295	    }),
296	  );
297	  const { critPct } = await nodeThresholds();
298	  const roomy = loads.filter((l) => l.projectedPct < critPct);
299	  const pool = roomy.length > 0 ? roomy : loads;
300	  pool.sort((a, b) => b.free - a.free);
301	  return pool[0].node;
302	}
