304	/** Validate + price an order without placing it. Throws OrderError on any problem. */
305	export async function orderQuote(intent: OrderIntent, opts?: { suppressPromo?: boolean }) {
306	  const parsed = orderSchema.safeParse(intent);
307	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
308	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
309	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
310	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
311	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
312	    throw new OrderError(
313	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
314	    );
315	  }
316	  const term = vpsTerm(Number(intent.termMonths ?? 1));
317	  // The admin-configured ANNUAL discount, resolved ONCE here and passed to
318	  // `vpsTermPriceCents` so the annual term is charged at the same rate the deploy
319	  // wizard displayed and every renewal will bill. Ignored for non-annual terms.
320	  const annualPct = await annualDiscountPct();
321	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
322	
323	  // Extra root disk, priced per GB/month and multiplied over the term exactly
324	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
325	  // promo — the customer pays the same $/GB whichever term they pick, and renews
326	  // at the same rate). Growth is one-way: this is permanent for the server.
327	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
328	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
329	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
330	  const extraDiskCents = extraDiskMonthlyCents * term.months;
331	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
332	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
333	  }
334	
335	  // Paid backup RETENTION tier, priced per month and multiplied over the term
336	  // exactly like the extra-disk add-on (NOT promo-discounted — the customer pays
337	  // the same $/mo whichever term or promo, and renews at the same rate through
338	  // renewalCharge). Only PLUS is paid; FREE (the included tier) is $0.
339	  const backupTier = normalizeBackupTier(intent.backupTier);
340	  const backupMonthlyCents =
341	    backupTier === "FREE" ? 0 : backupTierMonthlyCents(backupTier, await backupPlusMonthlyCents());
342	  const backupCents = backupMonthlyCents * term.months;
343	
344	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
345	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
346	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
347	  // real renewal price and this discounted value is the real first-term price.
348	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
349	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
350	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months, annualPct);
351	
352	  // LOW intro price → RENEWS at regular. A per-plan `introPriceCents` (set by an
353	  // admin) makes the FIRST term cheaper and leaves every renewal at the regular
354	  // `priceCents` — renewal code never reads the intro column, so renewal === regular
355	  // by construction (lib/renewal-charge.ts). Modelled as a first-term REDUCTION of
356	  // the regular term total (not a second price), so the regular term stays the one
357	  // basis renewals bill and proration prices against. `introDiscountCents` is 0 for
358	  // every plan without an intro price, so the whole VPS flow below is unchanged for
359	  // them. VPS never carries the first-month-free promo (`firstMonthFreeAppliesTo`),
360	  // so intro and FMF never stack here.
361	  const introMonthlyCents = planIntroMonthlyCents(plan);
362	  const introTermMonths = planIntroTermMonths(plan);
363	  const introDiscountCents = introFirstTermDiscountCents(
364	    plan.priceCents,
365	    introMonthlyCents,
366	    term.months,
367	    introTermMonths,
368	    annualPct,
369	  );
370	  // The plan-portion cash the FIRST term is sold at, intro applied. Renewals ignore it.
371	  const introFirstTermPlanCents = Math.max(0, regularPlanCents - introDiscountCents);
372	  // The rate this first term is sold at (percent off the regular term total) — stamped
373	  // on Server.termPromoPercent below via the promo object so proration/refunds price
374	  // against it exactly like a seasonal promo.
375	  const introPercent = introSoldPercent(regularPlanCents, introDiscountCents);
376	  const introRenewalMonthly = plan.priceCents; // what the "then $X/mo" copy quotes
377	  // When a plan has an intro price we present it THROUGH the same `promo` channel the
378	  // seasonal-sale plumbing uses (name + percent travel on OrderPrice and stamp
379	  // termPromoPercent). `firstMonthFree: false` keeps it out of the one-month-free
380	  // redemption machinery — an intro price has no per-account cap; it is simply this
381	  // plan's first-term price.
382	  const promo =
383	    introDiscountCents > 0
384	      ? {
385	          id: "intro-price",
386	          name: `Intro price — renews at $${(introRenewalMonthly / 100).toFixed(2)}/mo`,
387	          label: "Intro price",
388	          discountPercent: introPercent,
389	          firstMonthFree: false,
390	        }
391	      : currentPromo(new Date());
392	  // The promo is now MANAGED: the owner can switch it off, and every claim is
393	  // capped 1/account + 1/IP (lib/promo-redemption.ts). When the toggle is off the
394	  // quote shows — and placeOrder charges — the full price, so display === charged
395	  // on the disabled path. When it is on, the quote shows the first-month-free
396	  // price and the atomic claim in placeOrder's tx is the final arbiter of whether
397	  // the credit is actually granted (a lost race there is charged full).
398	  // `suppressPromo` prices this quote at FULL price even when the promo is on —
399	  // the card path uses it to re-quote for a customer who has already redeemed
400	  // (per-account/IP), so their Stripe leg and stamped total are full, not free.
401	  // The first-month-free promo is scoped to Shared Web Hosting only — VPS always
402	  // bills full. `firstMonthFreeAppliesTo("VPS")` is false, so promoEnabled is
403	  // false here and planFirstTermCents falls through to the regular term total.
404	  const promoEnabled =
405	    firstMonthFreeAppliesTo("VPS") && !opts?.suppressPromo && (await firstMonthFreeEnabled());
406	  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
407	  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
408	  // YEARS free. So we subtract one month of the plan's rate from the term total.
409	  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
410	  // 36-month term the customer pays the term minus one month. Renewals bill the
411	  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
412	  const planFirstTermCents =
413	    promoEnabled && promo.firstMonthFree
414	      ? Math.max(0, regularPlanCents - plan.priceCents)
415	      : regularPlanCents;
416	  // The one-month credit this order gets IF the atomic claim succeeds. 0 when the
417	  // promo is off. placeOrder adds it back to charge full when the claim is lost.
418	  const promoCreditCents = regularPlanCents - planFirstTermCents;
419	
420	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
421	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
422	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
423	  // so the deploy preview can show it; the redemption itself (count + per-user +
424	  // per-IP guards) is claimed atomically in placeOrder.
425	  let couponId: string | null = null;
426	  let couponDiscountCents = 0;
427	  let couponLabel = "";
428	  let couponError = "";
429	  let couponMaxRedemptions: number | null = null;
430	  let couponFirstTimeOnly = false;
431	  const code = (intent.couponCode ?? "").trim().toUpperCase();
432	  if (code) {
433	    if (!(await getSettingBool("coupons_enabled", true))) {
434	      couponError = "Promo codes are currently disabled.";
435	    } else {
436	      const coupon = await db.coupon.findUnique({ where: { code } });
437	      if (!coupon) {
438	        couponError = "That code isn’t valid.";
439	      } else {
440	        const verdict = couponOrderDiscountCents(
441	          {
442	            kind: coupon.kind,
443	            value: coupon.value,
444	            serviceKind: coupon.serviceKind,
445	            planSlug: coupon.planSlug,
446	            maxTermMonths: coupon.maxTermMonths,
447	            active: coupon.active,
448	            expiresAt: coupon.expiresAt,
449	            maxRedemptions: coupon.maxRedemptions,
450	            timesRedeemed: coupon.timesRedeemed,
451	            minAmountCents: coupon.minAmountCents,
452	          },
453	          {
454	            serviceKind: "VPS",
455	            planSlug: plan.slug,
456	            planMonthlyCents: plan.priceCents,
457	            termMonths: term.months,
458	            // Coupon discounts the intro-reduced plan portion, so an intro price and a
459	            // coupon cannot together drive the plan charge below zero, and a percentage
460	            // coupon is honestly "% off what you actually pay this term".
461	            planChargeCents: introFirstTermPlanCents,
462	          },
463	          new Date(),
464	        );
465	        if (verdict.ok) {
466	          couponId = coupon.id;
467	          couponDiscountCents = verdict.discountCents;
468	          couponLabel = verdict.label;
469	          couponMaxRedemptions = coupon.maxRedemptions;
470	          couponFirstTimeOnly = coupon.firstTimeOnly;
471	        } else {
472	          couponError = verdict.error;
473	        }
474	      }
475	    }
476	  }
477	
478	  const chargeCents = introFirstTermPlanCents - couponDiscountCents + ipCents + extraDiskCents + backupCents;
479	  return {
480	    plan,
481	    os,
482	    term,
483	    chargeCents,
484	    // Intro pricing (0 / null on plans without one). `introDiscountCents` is the
485	    // first-term saving already baked into `chargeCents`; `introFirstTermPlanCents`
486	    // is the plan-portion cash the first term is sold at; the monthly figures drive
487	    // the honest "$intro first term, then $regular/mo" copy on the pricing cards.
488	    introDiscountCents,
489	    introFirstTermPlanCents,
490	    introMonthlyCents,
491	    introTermMonths,
492	    introRenewalMonthly,
493	    introPercent,
494	    // The annual-discount rate this quote was priced at — snapshot onto the Server at
495	    // sale (Finding 2) so every later proration reads the SAME basis and a round trip
496	    // nets to zero even if the admin retunes `annual_discount_percent` in between.
497	    annualPct,
498	    promo,
499	    promoCreditCents,
500	    regularPlanCents,
501	    extraDiskGB,
502	    extraDiskMonthlyCents,
503	    extraDiskCents,
504	    backupTier,
505	    backupMonthlyCents,
506	    backupCents,
507	    couponId,
508	    couponDiscountCents,
509	    couponLabel,
510	    couponError,
511	    couponMaxRedemptions,
512	    couponFirstTimeOnly,
513	  };
514	}
