618	export async function placeOrder(
619	  user: User,
620	  intent: OrderIntent,
621	  sold?: OrderPrice | null,
622	  opts?: {
623	    ipHash?: string | null;
624	    campaign?: string;
625	    promoReservationToken?: string | null;
626	    couponReservationToken?: string | null;
627	  },
628	): Promise<string> {
629	  const quote = await orderQuote(intent);
630	  const { plan, os, term, promo, promoCreditCents, extraDiskGB, extraDiskMonthlyCents, extraDiskCents, backupTier, backupMonthlyCents, backupCents } = quote;
631	  // Everything below bills off THESE three, never off `quote.chargeCents` /
632	  // `promo` directly: when a sold price is present it is the whole truth about
633	  // what this order costs and what rate it was sold at.
634	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
635	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
636	  const promoName = sold?.promoName || promo.name;
637	
638	  // Managed first-month-free — how this order settles the credit depends on the path:
639	  //   WALLET path (no `sold`): the credit rides on the fresh quote (promoCreditCents
640	  //     > 0), and we contend for it with an atomic INSERT inside the charge tx below.
641	  //   CARD/Stripe path (`sold` present): the credit was already RESERVED before the
642	  //     card was charged, and its hold token travels in `opts.promoReservationToken`.
643	  //     We CONFIRM that hold (never a fresh contended INSERT) — that is what closes
644	  //     the double-claim race. No token => this order was sold at FULL price, so there
645	  //     is nothing to grant. We deliberately do NOT infer the credit from
646	  //     `sold.promoPercent` (currentPromo always stamps 100, even on a full-price VPS
647	  //     order), which would record a redemption for a purchase that never got one.
648	  const walletPromoApplied = !sold && promoCreditCents > 0;
649	  const cardPromoToken = sold ? opts?.promoReservationToken ?? null : null;
650	  // Note the intro discount on the billing document (first term only; renews full) —
651	  // ONLY when this specific order actually earned the credit (real customer report:
652	  // a full-price $8.88 VPS invoice read "First month free · 100% off first term",
653	  // because `promo.discountPercent` is a raw, ALWAYS-100 constant — see the comment
654	  // above — and this used to gate on that instead of on whether the credit was
655	  // actually granted to THIS order, same signal walletPromoApplied/cardPromoToken
656	  // already use to decide whether to grant it).
657	  const promoNote = walletPromoApplied || cardPromoToken ? ` · ${promoName} ${promoPercent}% off first term` : "";
658	  // The checkout coupon settles the same two ways:
659	  //   WALLET path (no `sold`): atomic claim in its OWN tx below (claimOrderCoupon), which
660	  //     throws and surfaces before any money moves if the last slot just went.
661	  //   CARD/Stripe path (`sold`): the coupon was RESERVED before the card was charged and
662	  //     its hold token travels in `opts.couponReservationToken`. We CONFIRM that hold
663	  //     inside the charge tx (never a fresh contended claim — that would double-count the
664	  //     global cap and collide on the per-person unique). No token => full-price order.
665	  const cardCouponToken = sold ? opts?.couponReservationToken ?? null : null;
666	
667	  const cap = await capacityCheck(plan.id);
668	  if (!cap.ok) throw new OrderError(cap.reason);
669	
670	  let nodeId: string | null = null;
671	  if (intent.nodeId) {
672	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
673	    if (!n) throw new OrderError("Selected location is not available.");
674	    nodeId = n.id;
675	  } else {
676	    const n = await scheduleNode(plan.ramMB);
677	    nodeId = n?.id ?? null;
678	  }
679	
680	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
681	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
682	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
683	
684	  const addons = {
685	    malwareScanner: !!intent.addonMalware,
686	    dailyBackup: !!intent.addonBackup,
687	    docker: !!intent.addonDocker,
688	  };
689	  const isAdmin = user.role === "ADMIN";
690	  const freeRequested = !!intent.free && isAdmin;
691	
692	  // VAT/GST to add to this order (Finding 1). CARD path: settle exactly the tax the
693	  // card leg was split from, carried on `sold` (never re-quoted after the card
694	  // cleared). WALLET path: resolve from the owner's billing country now. The RATE is
695	  // resolved here; the tax cents are recomputed from it inside the charge tx against
696	  // the amount actually debited, so a promo-lost full-price recompute is taxed on the
697	  // real net rather than the discounted one. A free admin grant is never taxed.
698	  let taxRatePercent = 0;
