1	/**
2	 * The free "Domain Inbox" mailbox that ships with every domain registered
3	 * through Nxeon (owner decision, 2026-08-27 — see prisma/seed-domain-inbox-plan.ts).
4	 *
5	 * Deliberately NOT a "use server" module. Every export of a "use server" file is
6	 * automatically a public, directly-invokable Server Action — but
7	 * `setupDomainInboxEmail` below trusts its `userId`/`domainName` arguments
8	 * completely and does no ownership check of its own (exactly like
9	 * `orderEmailHostingCore` in lib/actions-email-hosting.ts, which stays
10	 * UNEXPORTED for the same reason). Its only intended caller is `purchaseDomain`
11	 * in lib/actions-domains.ts, AFTER that action's own auth + impersonation +
12	 * ownership checks have already run and the domain is confirmed ACTIVE for
13	 * that user. Exporting this from a "use server" module would let any signed-in
14	 * client call it directly with an arbitrary userId/domainName — the exact
15	 * cross-tenant mailbox shape the 2026-07-25 takeover fix exists to prevent (see
16	 * the SECURITY comments on orderEmailHostingCore / addMailbox). Keeping this
17	 * file plain, with no directive, makes it importable by other server modules
18	 * while staying impossible to reach from the client.
19	 *
20	 * Mirrors (deliberately, in miniature) lib/hosting-email.ts's setupHostingEmail
21	 * — a complimentary EmailSubscription minted for a domain the caller already
22	 * controls, on a plan kept out of the paid storefront. Where hosting-bundled
23	 * email is external+unverified until DNS is proven, a domain that was JUST
24	 * REGISTERED through Nxeon is already ours to route mail for, so this mirrors
25	 * orderEmailHostingCore's "in-account" branch instead: external:false,
26	 * verified immediately, no DNS step for the customer to complete.
27	 */
28	
29	import { randomBytes } from "node:crypto";
30	import { db } from "./db";
31	import { encryptSecret } from "./crypto-box";
32	import { mailcowConfigured, mcCreateDomain, mcDomainExists, mcCreateMailbox } from "./mailcow";
33	
34	/** Must match prisma/seed-domain-inbox-plan.ts's NAME exactly. */
35	const DOMAIN_INBOX_PLAN_NAME = "Free Domain Inbox";
36	
37	// Same shape as lib/actions-email-hosting.ts's localPartRe — kept as a private
38	// copy rather than an import, since that file must not export anything a
39	// client could invoke as a Server Action (see file header above).
40	const localPartRe = /^[a-z0-9]+(?:[._-][a-z0-9]+)*$/;
41	
42	export type DomainInboxPlan = {
43	  id: string;
44	  name: string;
45	  mailboxes: number;
46	  storageGB: number;
47	};
48	
49	/**
50	 * The bundled, free plan every Nxeon-registered domain's inbox is created on.
51	 * Read-only lookup — safe to call from Server Components (e.g. the domains
52	 * list / register wizard, to show the real mailbox/GB numbers) as well as from
53	 * `setupDomainInboxEmail` below.
54	 */
55	export async function findDomainInboxPlan(): Promise<DomainInboxPlan | null> {
56	  return db.emailPlan.findFirst({
57	    where: { name: DOMAIN_INBOX_PLAN_NAME, priceCents: 0, active: false },
58	    select: { id: true, name: true, mailboxes: true, storageGB: true },
59	  });
60	}
61	
62	/**
63	 * Create the complimentary EmailSubscription — and, if the customer chose an
64	 * address during registration, the real mailbox — for a domain that was just
65	 * registered through Nxeon.
66	 *
67	 * Best-effort and NEVER throws: `purchaseDomain` has already charged the
68	 * customer and registered the domain at the regististrar by the time this
69	 * runs, so a missing plan seed or a Mailcow hiccup here must never surface as
70	 * a registration failure. A skipped/failed mailbox just leaves the
71	 * subscription in place with zero mailboxes — addable later from
72	 * /dashboard/email, same as any other subscription.
73	 *
74	 * NOT retroactive: this is only ever called at the moment of a NEW
75	 * registration. Domains already on the platform before this shipped are
76	 * never backfilled (a separate, larger cost decision the owner hasn't made).
77	 */
78	export async function setupDomainInboxEmail(params: {
79	  userId: string;
80	  domainName: string;
81	  expiresAt: Date | null;
82	  /** Local-part the customer chose during registration, if any (e.g. "hello"). */
83	  mailboxLocalPart?: string | null;
84	}): Promise<void> {
85	  const { userId, domainName, expiresAt } = params;
86	  try {
87	    // Global dedup — one subscription per domain across ALL accounts, the same
88	    // guard every other EmailSubscription creator uses (2026-07-25 fix). A
89	    // fresh registration should never collide, but never double-grant either.
90	    const dupe = await db.emailSubscription.findFirst({
91	      where: { domainName, status: { not: "CANCELLED" } },
92	    });
93	    if (dupe) return;
94	
95	    const plan = await findDomainInboxPlan();
96	    if (!plan) {
97	      console.warn(`[domain-inbox-email] "${DOMAIN_INBOX_PLAN_NAME}" plan not seeded — skipping ${domainName}`);
98	      return;
99	    }
100	
101	    const sub = await db.emailSubscription.create({
102	      data: {
103	        userId,
104	        domainName,
105	        emailPlanId: plan.id,
106	        status: "ACTIVE",
107	        autoRenew: true,
108	        termMonths: 1,
109	        expiresAt,
110	        // In-account domain — we just registered it, so we control its DNS.
111	        // Treat as verified immediately, mirroring orderEmailHostingCore's
112	        // in-account branch (no DNS step for the customer to complete).
113	        external: false,
114	        verified: true,
115	        verifiedAt: new Date(),
116	        verifyToken: null,
117	      },
118	    });
119	
120	    await db.auditLog
121	      .create({
122	        data: {
123	          userId,
124	          action: "domain.freeinbox.setup",
125	          detail: `${domainName} · ${plan.name} (${plan.mailboxes} mailbox, ${plan.storageGB} GB)`,
126	        },
127	      })
128	      .catch(() => {});
129	
130	    const local = String(params.mailboxLocalPart ?? "")
131	      .trim()
132	      .toLowerCase();
133	    // No address chosen — reserved but mailbox-less, same "add it later" state
134	    // orderEmailHostingCore leaves every fresh subscription in.
135	    if (!local) return;
136	    // A malformed choice is skipped rather than failing the domain purchase —
137	    // the paid transaction already succeeded and must not be undone by a
138	    // cosmetic mailbox-name typo. The customer can add a valid one later.
139	    if (!localPartRe.test(local) || local.length > 64) {
140	      console.warn(`[domain-inbox-email] invalid local-part "${local}" for ${domainName} — left mailbox-less`);
141	      return;
142	    }
143	
144	    const address = `${local}@${domainName}`;
145	    // Mailbox.address is GLOBALLY unique (2026-07-25 fix) — a collision here
146	    // just means someone else already holds that exact address; leave this
147	    // subscription mailbox-less rather than fail the registration.
148	    const existingMailbox = await db.mailbox.findUnique({ where: { address } });
149	    if (existingMailbox) {
150	      console.warn(`[domain-inbox-email] ${address} already exists — left ${domainName}'s inbox mailbox-less`);
151	      return;
152	    }
153	
154	    const quotaMB = plan.storageGB * 1024;
155	    const mailbox = await db.mailbox.create({
156	      data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
157	    });
158	
159	    if (!mailcowConfigured()) return; // left PROVISIONING, same as addMailbox()
160	
161	    try {
162	      if (!(await mcDomainExists(domainName))) {
163	        await mcCreateDomain(domainName).catch(() => {});
164	      }
165	      const password = randomBytes(18).toString("base64url");
166	      await mcCreateMailbox({ localPart: local, domain: domainName, name: address, password, quotaMB });
167	      await db.mailbox.update({
168	        where: { id: mailbox.id },
169	        data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
170	      });
171	    } catch (e) {
172	      await db.mailbox.update({ where: { id: mailbox.id }, data: { status: "FAILED" } }).catch(() => {});
173	      console.warn(`[domain-inbox-email] provisioning ${address} failed:`, e);
174	    }
175	  } catch (e) {
176	    console.warn(`[domain-inbox-email] setup for ${domainName} failed:`, e);
177	  }
178	}
