"use client";

/**
 * A real international phone input: a searchable country dropdown (flag +
 * dial code) plus a national-number field, backed by libphonenumber-js for
 * real per-country validation and live formatting — replacing the old plain
 * `+1.5551234567` free-text field (validated only against a shape regex,
 * never against whether the number could exist).
 *
 * The WIRE VALUE this emits is unchanged: `+<dialcode>.<nationalnumber>`,
 * exactly the format `purchaseDomain`'s zod schema
 * (`/^\+\d{1,3}\.\d{4,14}$/`) expects. This component is a client-side
 * affordance on top of that format, not a new format — the server-side
 * contract in lib/actions-domains.ts is untouched.
 *
 * No new icon/flag assets: country flags are Unicode regional-indicator
 * emoji, derived from the ISO-3166 alpha-2 code (two code points, no image,
 * no icon font, no CDN).
 */

import { useEffect, useMemo, useRef, useState } from "react";
import {
  AsYouType,
  getCountries,
  getCountryCallingCode,
  parsePhoneNumberFromString,
  type CountryCode,
} from "libphonenumber-js";

function flagEmoji(iso2: string): string {
  return String.fromCodePoint(...[...iso2.toUpperCase()].map((c) => 127397 + c.charCodeAt(0)));
}

// `Intl.DisplayNames` gives us real, localized country names with no hardcoded
// list to maintain — supported in Node 14+ and every modern browser, so this
// never needs an extra dependency or a data file.
const regionNames =
  typeof Intl !== "undefined" && "DisplayNames" in Intl
    ? new Intl.DisplayNames(["en"], { type: "region" })
    : null;

function countryName(iso2: string): string {
  return regionNames?.of(iso2) ?? iso2;
}

type CountryEntry = { code: CountryCode; name: string; dial: string; flag: string };

/** Built once at module load — libphonenumber-js's supported-country list never
 *  changes at runtime, so there is no reason to recompute this per render. */
const ALL_COUNTRIES: CountryEntry[] = getCountries()
  .map((code) => {
    let dial = "";
    try {
      dial = getCountryCallingCode(code);
    } catch {
      dial = "";
    }
    return { code, name: countryName(code), dial, flag: flagEmoji(code) };
  })
  .filter((c) => c.dial)
  .sort((a, b) => a.name.localeCompare(b.name));

/** Wire value ("+1.5551234567") -> best-guess ISO2 country, or null. Used only
 *  to seed the widget from an existing value (e.g. re-rendering with a value
 *  already typed); libphonenumber-js resolves the region from the full E.164
 *  string itself, so a shared dial code (NANP's +1, etc.) still lands on a
 *  sensible default. */
function countryFromWire(wire: string): CountryCode | null {
  const e164 = wire.replace(".", "");
  if (!e164.startsWith("+")) return null;
  return parsePhoneNumberFromString(e164)?.country ?? null;
}

function nationalFromWire(wire: string): string {
  const dot = wire.indexOf(".");
  return dot >= 0 ? wire.slice(dot + 1) : "";
}

export function PhoneCountryInput({
  value,
  onChange,
  defaultCountry = "US",
  id,
}: {
  /** Current wire value, e.g. "+1.5551234567", or "" when empty. */
  value: string;
  /** Fires on every edit with the wire value AND whether libphonenumber-js
   *  considers it a genuinely valid number for the selected country — never
   *  just a shape match. */
  onChange: (wire: string, valid: boolean) => void;
  /** ISO-3166 alpha-2 to preselect when `value` is empty — e.g. the country
   *  already chosen in the mailing-address field, for a sane first guess. Not
   *  force-synced afterward: a customer's phone country can legitimately
   *  differ from their mailing address. */
  defaultCountry?: string;
  id?: string;
}) {
  const [country, setCountry] = useState<CountryCode>(
    () => countryFromWire(value) ?? (ALL_COUNTRIES.some((c) => c.code === defaultCountry) ? (defaultCountry as CountryCode) : "US"),
  );
  const [national, setNational] = useState<string>(() => {
    const raw = nationalFromWire(value);
    return raw ? new AsYouType(country).input(raw) : "";
  });
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const boxRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    function onDocClick(e: MouseEvent) {
      if (boxRef.current && !boxRef.current.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [open]);

  const selected = useMemo(() => ALL_COUNTRIES.find((c) => c.code === country) ?? ALL_COUNTRIES[0], [country]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return ALL_COUNTRIES;
    return ALL_COUNTRIES.filter(
      (c) => c.name.toLowerCase().includes(q) || c.dial.includes(q) || c.code.toLowerCase().includes(q),
    );
  }, [query]);

  function emit(nextCountry: CountryCode, nextDisplay: string) {
    const digits = nextDisplay.replace(/\D/g, "");
    if (!digits) {
      onChange("", false);
      return;
    }
    let dial = "";
    try {
      dial = getCountryCallingCode(nextCountry);
    } catch {
      dial = "";
    }
    if (!dial) {
      onChange("", false);
      return;
    }
    const wire = `+${dial}.${digits}`;
    const parsed = parsePhoneNumberFromString(`+${dial}${digits}`, nextCountry);
    onChange(wire, !!parsed?.isValid());
  }

  function handleNationalChange(raw: string) {
    const digitsOnly = raw.replace(/[^\d]/g, "");
    const formatted = new AsYouType(country).input(digitsOnly);
    setNational(formatted);
    emit(country, formatted);
  }

  function pickCountry(code: CountryCode) {
    setCountry(code);
    setOpen(false);
    setQuery("");
    // Re-format whatever digits are already typed for the new country, and
    // re-validate against it — a number valid for one country's numbering
    // plan is not automatically valid for another's.
    const digits = national.replace(/\D/g, "");
    const formatted = digits ? new AsYouType(code).input(digits) : "";
    setNational(formatted);
    emit(code, formatted);
  }

  return (
    <div className="flex max-w-md items-stretch gap-0" ref={boxRef}>
      <div className="relative">
        <button
          type="button"
          onClick={() => setOpen((o) => !o)}
          className="input flex h-full items-center gap-1.5 rounded-r-none border-r-0 px-3 text-sm"
          aria-haspopup="listbox"
          aria-expanded={open}
        >
          <span className="text-base leading-none">{selected.flag}</span>
          <span className="text-slate-300">+{selected.dial}</span>
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-slate-500">
            <path d="m6 9 6 6 6-6" />
          </svg>
        </button>
        {open && (
          <div className="absolute left-0 top-full z-20 mt-1 w-72 overflow-hidden rounded-xl border border-white/[0.08] bg-navy-900 shadow-xl">
            <div className="border-b border-white/[0.06] p-2">
              <input
                autoFocus
                className="input text-sm"
                placeholder="Search country or code…"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
              />
            </div>
            <ul className="max-h-64 overflow-y-auto py-1" role="listbox">
              {filtered.length === 0 && <li className="px-3 py-2 text-sm text-slate-500">No match.</li>}
              {filtered.map((c) => (
                <li key={c.code}>
                  <button
                    type="button"
                    onClick={() => pickCountry(c.code)}
                    className={`flex w-full items-center gap-2 px-3 py-1.5 text-left text-sm hover:bg-white/[0.05] ${
                      c.code === country ? "bg-brand-500/10 text-brand-200" : "text-slate-300"
                    }`}
                    role="option"
                    aria-selected={c.code === country}
                  >
                    <span className="text-base leading-none">{c.flag}</span>
                    <span className="min-w-0 flex-1 truncate">{c.name}</span>
                    <span className="text-slate-500">+{c.dial}</span>
                  </button>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
      <input
        id={id}
        className="input rounded-l-none"
        inputMode="tel"
        value={national}
        onChange={(e) => handleNationalChange(e.target.value)}
        placeholder="555 123 4567"
      />
    </div>
  );
}

/** Real per-country validity of a wire-format value ("+1.5551234567"), for
 *  callers that only hold the wire string (not this component's internal
 *  country/national state) — e.g. a parent's cross-step "can I continue?"
 *  check. Never just the `PHONE_RE` shape match: a shape-valid string like
 *  "+1.0000000000" is still not a real number. */
export function isValidWirePhone(wire: string): boolean {
  if (!wire) return false;
  const e164 = wire.replace(".", "");
  if (!e164.startsWith("+")) return false;
  return !!parsePhoneNumberFromString(e164)?.isValid();
}

