/**
 * Geoapify address autocomplete/geocoding — gated entirely on GEOAPIFY_API_KEY.
 *
 * No key exists in this environment yet (the owner will add the real value to
 * the live `.env` themselves). Every caller checks `geoapifyConfigured()` first
 * and degrades to the plain, always-worked text inputs when it's false — same
 * "don't claim a feature that isn't provisioned" rule the free-inbox plan
 * (`lib/domain-inbox-email.ts`) follows for the Email step. The API key itself
 * NEVER reaches the client — every call goes through this plain server module,
 * used only from the `/api/geoapify/autocomplete` route handler.
 */

export function geoapifyConfigured(): boolean {
  return !!process.env.GEOAPIFY_API_KEY;
}

export type GeoapifySuggestion = {
  formatted: string;
  address1: string;
  city: string;
  stateProvince: string;
  postalCode: string;
  /** ISO-3166 alpha-2, uppercased. */
  country: string;
  /** Geoapify's own match confidence, 0–1. Advisory only — never used to block
   *  a submission, only to flag a possibly-mistyped address (see the wizard's
   *  Street address field). */
  confidence: number;
};

/**
 * Proxy Geoapify's Autocomplete API (also used, with a full free-text query, as
 * the "does this typed address resolve to anything real" confidence check —
 * Geoapify's autocomplete endpoint is built on the same geocoder and returns
 * the same `rank.confidence`/`rank.match_type` fields a dedicated geocode call
 * would, so one proxy route serves both jobs).
 *
 * Throws on a transport/HTTP failure — callers decide how to degrade (the
 * route handler turns a throw into an empty, non-fatal result; nothing here
 * silently invents a "no suggestions" answer that hides a real outage).
 */
export async function geoapifyAutocomplete(
  text: string,
  countryBias?: string,
): Promise<GeoapifySuggestion[]> {
  const apiKey = process.env.GEOAPIFY_API_KEY;
  if (!apiKey) throw new Error("Geoapify is not configured");
  const params = new URLSearchParams({
    text,
    type: "amenity", // widest match type; still returns building/street-level results
    format: "json",
    limit: "5",
    apiKey,
  });
  // Bias (not filter): a customer's mailing address can legitimately be in a
  // different country than the one their account/domain search defaults to, so
  // this must never EXCLUDE other countries' results, only prefer the hinted one.
  if (countryBias && /^[A-Za-z]{2}$/.test(countryBias)) {
    params.set("bias", `countrycode:${countryBias.toLowerCase()}`);
  }
  const res = await fetch(`https://api.geoapify.com/v1/geocode/autocomplete?${params.toString()}`, {
    signal: AbortSignal.timeout(8_000),
  });
  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new Error(`Geoapify: HTTP ${res.status}${body ? ` — ${body.slice(0, 200)}` : ""}`);
  }
  const json = await res.json();
  const results: any[] = Array.isArray(json?.results) ? json.results : [];
  return results.map((r) => ({
    formatted: String(r.formatted ?? ""),
    address1: String(r.address_line1 ?? r.formatted ?? ""),
    city: String(r.city ?? r.county ?? ""),
    stateProvince: String(r.state ?? ""),
    postalCode: String(r.postcode ?? ""),
    country: String(r.country_code ?? "").toUpperCase(),
    confidence: typeof r.rank?.confidence === "number" ? r.rank.confidence : 0,
  }));
}

