import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { geoapifyConfigured, geoapifyAutocomplete } from "@/lib/geoapify";

export const dynamic = "force-dynamic";

/**
 * Server-side proxy for Geoapify's Autocomplete API — the GEOAPIFY_API_KEY never
 * reaches the client bundle. Serves two jobs from the domain-register wizard's
 * Contact step, both reading this same endpoint (see lib/geoapify.ts's doc
 * comment for why one proxy covers both):
 *   1. The debounced dropdown as the customer types their street address.
 *   2. A light confidence check on whatever they end up with (typed or picked)
 *      — advisory only, never a hard block.
 *
 * Signed-in only and rate-limited per user, the same shape as
 * app/api/domains/check/route.ts's registrar-lookup guard: this calls a metered
 * third-party API, and it is only ever used from an authenticated dashboard page.
 */
export async function GET(req: NextRequest) {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  if (!geoapifyConfigured()) {
    // The wizard only renders the autocomplete UI when the server component's
    // own `geoapifyConfigured()` read said yes, so reaching this with no key
    // configured means the key was pulled after the page loaded — degrade
    // quietly rather than error.
    return NextResponse.json({ configured: false, results: [] });
  }

  const rl = checkRateLimit(`geoapify:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "rate limited", retryAfterSec: rl.retryAfterSec, results: [] },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } },
    );
  }

  const q = (req.nextUrl.searchParams.get("q") ?? "").trim();
  if (q.length < 3) return NextResponse.json({ configured: true, results: [] });
  const country = req.nextUrl.searchParams.get("country") ?? undefined;

  try {
    const results = await geoapifyAutocomplete(q, country);
    return NextResponse.json({ configured: true, results });
  } catch (e) {
    // Best-effort: a Geoapify hiccup must never break the Contact step — the
    // field is a plain input underneath the dropdown either way.
    return NextResponse.json({
      configured: true,
      results: [],
      error: String(e instanceof Error ? e.message : e).slice(0, 200),
    });
  }
}

"use client";

/**
 * Debounced Street-address autocomplete, wired to /api/geoapify/autocomplete.
 * Only ever mounted when the server already confirmed GEOAPIFY_API_KEY is set
 * (components/customer/DomainRegisterWizard.tsx's `geoapifyEnabled` prop) — this
 * component assumes the endpoint is live and simply degrades to "no dropdown"
 * on a transient failure, it never has to decide whether the feature exists.
 *
 * Same debounce/dropdown shape as the domain-search box earlier in this same
 * wizard (a 400ms timer + a `results`/`searching` pair), reused rather than
 * reinvented for a second free-text field.
 */

import { useEffect, useRef, useState } from "react";

export type AddressSuggestion = {
  formatted: string;
  address1: string;
  city: string;
  stateProvince: string;
  postalCode: string;
  country: string;
};

export function AddressAutocompleteInput({
  value,
  onChangeText,
  onSelect,
  countryBias,
  maxLength,
  placeholder,
}: {
  value: string;
  onChangeText: (v: string) => void;
  onSelect: (s: AddressSuggestion) => void;
  /** ISO-3166 alpha-2 — biases (never filters) results toward this country. */
  countryBias?: string;
  maxLength?: number;
  placeholder?: string;
}) {
  const [results, setResults] = useState<AddressSuggestion[] | null>(null);
  const [searching, setSearching] = useState(false);
  const [open, setOpen] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const boxRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (timer.current) clearTimeout(timer.current);
    const q = value.trim();
    if (q.length < 4) {
      setResults(null);
      setSearching(false);
      return;
    }
    setSearching(true);
    timer.current = setTimeout(async () => {
      try {
        const params = new URLSearchParams({ q });
        if (countryBias) params.set("country", countryBias);
        const res = await fetch(`/api/geoapify/autocomplete?${params.toString()}`, { cache: "no-store" });
        const json: { results?: AddressSuggestion[] } = await res.json();
        setResults(json.results ?? []);
        setOpen(true);
      } catch {
        setResults([]);
      }
      setSearching(false);
    }, 400);
    return () => {
      if (timer.current) clearTimeout(timer.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value, countryBias]);

  useEffect(() => {
    function onDocClick(e: MouseEvent) {
      if (boxRef.current && !boxRef.current.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, []);

  return (
    <div className="relative" ref={boxRef}>
      <input
        className="input"
        value={value}
        onChange={(e) => {
          onChangeText(e.target.value);
          setOpen(true);
        }}
        onFocus={() => results && results.length > 0 && setOpen(true)}
        maxLength={maxLength}
        placeholder={placeholder}
        autoComplete="off"
      />
      {searching && (
        <span className="absolute right-3 top-1/2 -translate-y-1/2 block h-3.5 w-3.5 animate-spin rounded-full border-2 border-slate-500 border-t-brand-400" />
      )}
      {open && results && results.length > 0 && (
        <ul className="absolute left-0 right-0 top-full z-20 mt-1 max-h-64 overflow-y-auto rounded-xl border border-white/[0.08] bg-navy-900 shadow-xl">
          {results.map((s, i) => (
            <li key={`${s.formatted}-${i}`}>
              <button
                type="button"
                onClick={() => {
                  onSelect(s);
                  setOpen(false);
                  setResults(null);
                }}
                className="block w-full truncate px-3 py-2 text-left text-sm text-slate-300 hover:bg-white/[0.05]"
                title={s.formatted}
              >
                {s.formatted}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

