/** The frozen per-year price a domain order was quoted at — see
 *  `DomainOrderIntent`'s doc comment in schema.prisma for why the registrant
 *  contact rides in our own DB (referenced by `domainOrderId`) rather than in
 *  Stripe metadata, while this small pair of integers travels in metadata like
 *  every other order kind's price. */
export type DomainOrderPrice = { priceCents: number; costCents: number };

/**
 * The card-leg analogue of `createOrderCheckout`/`createHostingOrderPaymentSession`
 * for a domain registration. `amountCents` is the CARD leg only (the shortfall
 * after the customer's wallet balance); `sold` is the retail/cost-per-year pair
 * `purchaseDomain` already fetched from the registrar via `checkDomains` at the
 * moment this session opens — frozen here and never re-quoted at fulfilment,
 * same anti-drift rule `OrderPrice` documents for VPS orders (a registrar price
 * can legitimately move between "customer clicked Register" and "card cleared";
 * re-quoting after the card is charged is the H2 incident from a different
 * angle). `domainOrderId` points at the `DomainOrderIntent` row `purchaseDomain`
 * already wrote with this exact contact + price, which is what fulfilment
 * (`placeDomainCardOrder`) actually reads to register the domain — this
 * function's `sold` param exists so the "card leg cannot exceed the total"
 * refusal below can run at session-creation time without a DB round trip.
 */
export async function createDomainOrderPaymentSession(
  user: CardUser,
  amountCents: number,
  domainName: string,
  years: number,
  domainOrderId: string,
  sold: DomainOrderPrice,
): Promise<CustomCheckout | null> {
  if (!stripeConfigured() || amountCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const orderTotalCents = domainTermPriceCents(sold.priceCents, years);
  if (orderTotalCents < amountCents) {
    throw new Error(`Domain order payment session: card leg ${amountCents}c exceeds the order total ${orderTotalCents}c`);
  }
  const { ensureStripeCustomer } = await import("./stripe-cards");
  const customerId = await ensureStripeCustomer(user);
  const session = await stripe().checkout.sessions.create(
    {
      mode: "payment",
      customer: customerId,
      payment_method_types: ["card"],
      payment_intent_data: { setup_future_usage: "off_session" },
      // Custom Checkout's client-side `checkout.confirm({ savePaymentMethod })`
      // (components/customer/PaymentStep.tsx) throws `IntegrationError:
      // savePaymentMethod cannot be used unless the Checkout Session was created
      // with saved_payment_method_options[payment_method_save]=enabled` without
      // this — the same bug fixed across every other order session-builder above.
      saved_payment_method_options: { payment_method_save: "enabled" },
      expires_at: Math.floor((Date.now() + ORDER_CHECKOUT_EXPIRES_MS) / 1000),
      line_items: [
        {
          price_data: { currency: "usd", product_data: { name: `Nxeon Domain — ${domainName}` }, unit_amount: amountCents },
          quantity: 1,
        },
      ],
      metadata: {
        nxeonUserId: user.id,
        // Just a reference id — see DomainOrderPrice's doc comment above for why
        // the full registrant contact does not ride here like other order kinds'.
        nxeonDomainOrder: packMetadata("Domain order intent", { domainOrderId }),
        nxeonDomainOrderPrice: packMetadata("Domain order price", sold),
      },
      ui_mode: CUSTOM_CHECKOUT_UI_MODE,
      return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
    },
    EMBEDDED_REQUEST_OPTS,
  );
  return session.client_secret ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : null;
}

/** The card-leg analogue of the plain wallet top-up (`app/api/stripe/checkout`'s

/** A business-email order funded by card — the email analogue of `hostOrder`. */
| { kind: "emailOrder"; userId: string; intent: EmailOrderCheckoutIntent }
/** A domain registration funded by card. `domainOrderId` points at the
 *  `DomainOrderIntent` row `placeDomainCardOrder` reads for the actual
 *  registrant contact + price; `sold` is a metadata-only mirror of that row's
 *  price, present so a malformed/missing price never turns this into
 *  `unreadable` (the row, not the metadata, is what fulfilment charges). */
| { kind: "domainOrder"; userId: string; domainOrderId: string; sold: DomainOrderPrice | null }

  // Domain registration funded by card. `domainOrderId` is the one thing that
  // must parse — without it fulfilment has nothing to look up and this must
  // never fall through to a silent top-up. The price mirror is best-effort: a
  // bad/missing `nxeonDomainOrderPrice` still classifies as a domainOrder with
  // `sold: null`, because the DomainOrderIntent row (not this metadata) is the
  // value `placeDomainCardOrder` actually charges.
  const domainRaw = md?.nxeonDomainOrder;
  if (domainRaw) {
    let p: Record<string, unknown>;
    try {
      p = JSON.parse(domainRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonDomainOrder is not valid JSON" };
    }
    const domainOrderId = parseId(p?.domainOrderId);
    if (!domainOrderId) {
      return { kind: "unreadable", userId, detail: "nxeonDomainOrder is missing domainOrderId" };
    }
    let sold: DomainOrderPrice | null = null;
    const priceRaw = md?.nxeonDomainOrderPrice;
    if (priceRaw) {
      try {
        const sp = JSON.parse(priceRaw) as Record<string, unknown>;
        const priceCents = parseChargeCents(sp?.priceCents);
        const costCents = parseChargeCents(sp?.costCents);
        if (priceCents !== null && costCents !== null) sold = { priceCents, costCents };
      } catch {
        sold = null;
      }
    }
    return { kind: "domainOrder", userId, domainOrderId, sold };
  }

  return { kind: "topup", userId };
}

