/**
 * Raised by `registerDomainCore` for anything that stops BEFORE a `Domain` row
 * exists (duplicate name, insufficient balance) — the caller shows `e.message`
 * verbatim, exactly like the inline `return { error }`s this replaced.
 */
class DomainOrderError extends Error {}

/**
 * What actually happened once a `Domain` row was created and the registrar was
 * called — the three-way outcome `purchaseDomain` always had, now a return
 * value instead of being baked into one function's control flow, so both the
 * wallet path and the card-fulfilment path can react to it identically.
 */
type DomainRegistrationResult =
  | { kind: "active"; domainId: string }
  | { kind: "refunded"; domainId: string; message: string }
  | { kind: "needs-review"; domainId: string; message: string };

/**
 * The registrar call + wallet debit + `Domain` row create/update + verify-on-
 * failure + `setupDomainInboxEmail` — extracted verbatim from `purchaseDomain`
 * so BOTH the direct-wallet action below and the card-fulfilment path
 * (`placeDomainCardOrder`) run the exact same money-and-registrar logic against
 * a FROZEN `priced` (never a fresh `checkDomains` re-quote taken here — the
 * caller already fetched it, at session-creation time for the card path, and
 * that is the one and only quote this purchase is ever priced against).
 *
 * Deliberately UNEXPORTED (this file has `"use server"`, so every export
 * becomes a client-invokable Server Action). `user` is trusted completely —
 * its `id` and `balanceCents` drive a real wallet debit — so this must only
 * ever be reachable from a caller that already resolved `user` itself
 * (`purchaseDomain`'s `requireUser()`, or `placeDomainCardOrder`'s verified
 * Stripe session), never from a client-suppliable argument. Same reasoning as
 * `orderEmailHostingCore` staying unexported in lib/actions-email-hosting.ts
 * (see lib/domain-inbox-email.ts's header comment).
 */
async function registerDomainCore(
  user: User,
  params: {
    domain: string;
    years: number;
    contact: RegistrantContact;
    mailboxLocalPart: string | null;
    partnerSource: string | null;
  },
  priced: DomainOrderPrice,
): Promise<DomainRegistrationResult> {
  const { domain, contact, mailboxLocalPart, partnerSource } = params;
  const dTerm = domainTerm(params.years);
  const totalCents = domainTermPriceCents(priced.priceCents, dTerm.years);
  const registrarCostCents = priced.costCents * dTerm.years;

  const existing = await db.domain.findUnique({ where: { name: domain } });
  if (existing) {
    if (existing.userId !== user.id) throw new DomainOrderError("This domain is already managed by another account.");
    if (existing.status === "PENDING") {
      throw new DomainOrderError("You already have a registration in progress for this domain.");
    }
    throw new DomainOrderError(`You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).`);
  }

  if (user.balanceCents < totalCents) {
    throw new DomainOrderError(`Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}.`);
  }

  let record;
  try {
    record = await db.$transaction(async (tx) => {
      // Re-check inside the transaction: the availability round-trip above is
      // slow enough for a second submit to slip in. `Domain.name` is UNIQUE, so
      // even if this read misses, the create below rolls the whole debit back.
      const dupe = await tx.domain.findUnique({ where: { name: domain }, select: { id: true } });
      if (dupe) throw new DuplicateDomainError();
      await debitWallet(tx, user.id, totalCents);
      await tx.walletTransaction.create({
        data: { userId: user.id, amountCents: -totalCents, description: `Domain registration: ${domain} (${dTerm.label})` },
      });
      return tx.domain.create({
        data: {
          name: domain,
          userId: user.id,
          priceCents: priced.priceCents,
          costCents: priced.costCents,
          termYears: dTerm.years,
          status: "PENDING",
          registrar: "name.com",
          partnerSource: partnerSource ?? null,
        },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) throw new DomainOrderError("Insufficient balance — top up your wallet first.");
    if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
      throw new DomainOrderError("This domain is already being registered — you have not been charged twice.");
    }
    throw e;
  }

  try {
    const { expiresAt } = await registerDomain(domain, dTerm.years, contact, registrarCostCents);
    const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
    await db.domain.update({
      where: { id: record.id },
      data: {
        status: "ACTIVE",
        registeredAt: new Date(),
        expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
      },
    });
    await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: `${domain} ${dTerm.years}yr` } });
    await db.notification.create({
      data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
    });
    // Tell the partner (best-effort, never blocks the order) — only for orders
    // tagged via a partner deep link. Most domain registrations are direct Nxeon
    // customers and must never be forwarded to a partner's webhook.
    if (partnerSource === "kodely") {
      await notifyPartner("domain.registered", { userId: user.id, domain, expiresAt: info.expires ?? null });
    }
    // Every domain registered through Nxeon includes a free inbox — see
    // lib/domain-inbox-email.ts. Best-effort: never lets a mailbox hiccup
    // undo a domain purchase that already succeeded.
    await setupDomainInboxEmail({
      userId: user.id,
      domainName: domain,
      expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
      mailboxLocalPart,
    });
    return { kind: "active", domainId: record.id };
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 400);
    // NEVER refund blind: a timeout/5xx often means the order DID go through.
    const verdict = await verifyRegistration(domain);

    if (verdict.state === "registered") {
      // The registration exists — keep the charge and finish the record.
      await db.domain.update({
