          db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
          db.walletTransaction.create({
            data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
          }),
          db.domain.update({
            where: { id: record.id },
            data: { status: "FAILED", error: reason.slice(0, 500) },
          }),
        ]);
        return { error: `Registration failed: ${reason.slice(0, 200)} (you were refunded).` };
      }

      // Unknown: leave PENDING and charged, flag for manual review. Refunding
      // here risks giving away a domain we actually paid the registrar for.
      await db.domain.update({
        where: { id: record.id },
        data: { status: "PENDING", error: `NEEDS REVIEW — registrar status unconfirmed: ${reason}`.slice(0, 500) },
      });
      await db.auditLog.create({
        data: { userId: user.id, action: "domain.register.needs_review", detail: `${domain}: ${reason}`.slice(0, 500) },
      });
      await db.notification.create({
        data: {
          userId: user.id,
          title: `Domain ${domain} needs review`,
          body: "We could not confirm the registration with the registrar. Our team is checking it — no duplicate charge will be made.",
          href: `/dashboard/domains/${record.id}`,
        },
      });
      return {
        error:
          `We could not confirm ${domain} with the registrar (${reason.slice(0, 120)}). ` +
          `It is marked for review — do not retry, you will not be charged twice.`,
      };
    }
    redirect(`/dashboard/domains/${record.id}?new=1`);
  } finally {
    endSubmit(guardKey);
  }
}

