2	import assert from "node:assert/strict";
3	import { readFileSync } from "node:fs";
4	import { join } from "node:path";
5	import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";
6	
7	/**
8	 * Structural guards over the CUSTOMER-FACING SERVER ACTIONS.
9	 *
10	 * These are the functions the portal calls to act on a customer's behalf, and
11	 * they are the widest attack surface in the product for one reason that is easy
12	 * to forget while reading them: **every export of a `"use server"` file is a
13	 * public network endpoint**. Not "callable from the page that imports it" —
14	 * callable by a stranger with curl. That property is what turned
15	 * `verifyTotpForUser` into an unauthenticated 2FA brute-force oracle
16	 * (QA-PRELAUNCH P0-2) and is why `lib/safe-next.ts` and `lib/totp-verify.ts`
17	 * exist as plain modules.
18	 *
19	 * A reviewer can hold that in their head for one file. Nobody holds it for
20	 * fifteen, forever, while adding a sixteenth. So it is asserted here instead.
21	 *
22	 * ── WHY THE SOURCE IS STRIPPED OF COMMENTS FIRST ─────────────────────────────
23	 * This codebase documents its incidents in the code, at length. A tripwire that
24	 * greps raw source for `assertNotImpersonating` matches the comment explaining
25	 * why the guard matters — so it passes on a function whose guard was deleted and
26	 * whose comment survived, which is the exact edit a careless refactor makes.
27	 * `stripComments` removes comments (and only comments) before anything is
28	 * matched, so every assertion below is about executable code.
29	 */
30	
31	const LIB = join(import.meta.dirname, "..", "lib");
32	
33	/* ------------------------------------------------------------------ *
34	 * Source utilities
35	 * ------------------------------------------------------------------ */
36	
37	/**
38	 * Remove `//` and slash-star comments while preserving string and template
39	 * literals verbatim (a `"https://…"` is not a comment, and neither is the `//`
40	 * inside `/^https?:\/\//`). Replaces each comment with a single space so token
41	 * boundaries survive.
42	 */
43	
44	
45	function source(file: string): string {
46	  return stripComments(readFileSync(join(LIB, file), "utf8"));
47	}
48	
49	/** Every `export async function NAME` in a (comment-stripped) module. */
50	function exportedActions(src: string): string[] {
51	  return [...src.matchAll(/export\s+async\s+function\s+([A-Za-z0-9_$]+)\s*\(/g)].map((m) => m[1]);
52	}
53	
54	/**
55	 * The body of `export async function NAME`, by brace matching from its opening
56	 * `{`. Braces inside strings are ignored — every string literal in these files
57	 * is balanced anyway, but template literals interpolate `${…}` and must not be
58	 * allowed to unbalance the count.
59	 */
60	function bodyOf(src: string, name: string): string {
61	  const decl = new RegExp(`export\\s+async\\s+function\\s+${name}\\s*\\(`).exec(src);
62	  assert.ok(decl, `expected to find an exported action named ${name}`);
63	
64	  // Walk the parameter list to its closing paren, then find the body's opening
65	  // brace. The brace cannot simply be "the next `{`": a return annotation like
66	  // `Promise<{ error?: string }>` puts one in the way, and matching from there
67	  // returns the TYPE instead of the body — which silently makes every assertion
68	  // about that function vacuous. So skip braces that sit inside `<…>`.
69	  let i = src.indexOf("(", decl.index);
70	  let parens = 0;
71	  let quote: string | null = null;
72	  for (; i < src.length; i++) {
73	    const c = src[i];
74	    if (quote) {
75	      if (c === "\\") i++;
76	      else if (c === quote) quote = null;
77	      continue;
78	    }
79	    if (c === '"' || c === "'" || c === "`") quote = c;
80	    else if (c === "(") parens++;
81	    else if (c === ")" && --parens === 0) break;
82	  }
83	  assert.ok(i < src.length, `unbalanced parameter list for ${name}`);
84	
85	  let angles = 0;
86	  for (i++; i < src.length; i++) {
87	    const c = src[i];
88	    if (c === "<") angles++;
89	    else if (c === ">") angles = Math.max(0, angles - 1);
90	    else if (c === "{" && angles === 0) break;
91	  }
92	  assert.ok(i < src.length, `no body found for ${name}`);
93	  const start = i;
94	  let depth = 0;
95	  quote = null;
96	  for (; i < src.length; i++) {
97	    const c = src[i];
98	    if (quote) {
99	      if (c === "\\") {
100	        i++;
101	        continue;
102	      }
103	      if (c === quote) quote = null;
104	      continue;
105	    }
106	    if (c === '"' || c === "'" || c === "`") {
107	      quote = c;
108	      continue;
109	    }
110	    if (c === "{") depth++;
111	    else if (c === "}") {
112	      depth--;
113	      if (depth === 0) return src.slice(start, i + 1);
114	    }
115	  }
116	  assert.fail(`unbalanced body for ${name}`);
117	}
118	
119	/* ------------------------------------------------------------------ *
120	 * 0. The stripper itself must bite
121	 * ------------------------------------------------------------------ */
122	
123	test("stripComments removes the incident notes a naive grep would match", () => {
124	  const src = `
125	    // Spend path: this needs assertNotImpersonating().
126	    /* debitWallet is called below — see assertNotImpersonating. */
127	    export async function pay() { await debitWallet(tx, id, 1); }
128	  `;
129	  const stripped = stripComments(src);
130	  assert.equal(stripped.includes("assertNotImpersonating"), false);
131	  assert.ok(stripped.includes("debitWallet(tx, id, 1)"));
132	});
133	
134	test("stripComments leaves string and regex contents alone", () => {
135	  const src = String.raw`const a = "see https://example.com/x"; const b = /^https?:\/\//; // gone`;
136	  const stripped = stripComments(src);
137	  assert.ok(stripped.includes("https://example.com/x"), "a URL inside a string is not a comment");
138	  assert.ok(stripped.includes(String.raw`/^https?:\/\//`), "an escaped slash in a regex is not a comment");
139	  assert.equal(stripped.includes("gone"), false);
140	});
141	
142	/* ------------------------------------------------------------------ *
143	 * 1. Nothing reaches a stranger unauthenticated
144	 * ------------------------------------------------------------------ */
145	
146	/** The customer-facing action modules audited here. All carry `"use server"`. */
147	const ACTION_FILES = [
148	  "actions.ts",
149	  "actions-server.ts",
150	  "actions-server-lifecycle.ts",
151	  "actions-volumes.ts",
152	  "actions-domains.ts",
153	  "actions-domains-transfer.ts",
154	  "actions-disk.ts",
155	  "actions-gameplans.ts",
156	  "actions-growth.ts",
157	  "actions-affiliate.ts",
158	  "actions-onboarding.ts",
159	  "actions-support.ts",
160	  "actions-settings.ts",
161	  "actions-migrate.ts",
162	  "actions-ssl.ts",
163	  "actions-claude.ts",
164	] as const;
165	
166	/**
167	 * Calls that establish WHO is asking. `owned*` are this codebase's per-resource
168	 * helpers, each of which starts with `requireUser()` and then proves ownership.
169	 */
170	const AUTH_MARKERS = [
171	  "requireUser(",
172	  "requireAdmin(",
173	  "requireArea(",
174	  "requireStaff(",
175	  "realUser(",
176	  "ownedServer(",
177	  "ownedVolume(",
178	  "ownedDomain(",
179	  "ownedCertificate(",
180	  "ownedTargetServer(",
181	  // Verified before adding: `ownedMigrationForRemediation` (lib/actions-migrate.ts)
182	  // starts with `requireUser()` and then rejects unless the caller owns the
183	  // migration or is an ADMIN — the same shape as `ownedTargetServer` above.
184	  "ownedMigrationForRemediation(",
185	  "assertInternalGrowthCaller(",
186	  // Verified before adding: `requireTicketActor` (lib/actions-support.ts) calls
187	  // `requireUser()` and derives staff status from `canAccess(role, "support")`.
188	  // It is listed because it genuinely authenticates — NOT because three tests
189	  // were red. Adding a name here without reading the helper is how a guard list
190	  // becomes a list of names that merely look reassuring.
191	  "requireTicketActor(",
192	];
193	
194	/**
195	 * The only endpoints that are SUPPOSED to answer an anonymous caller: the
196	 * sign-up / sign-in / sign-out trio. Each rate-limits itself; see lib/actions.ts.
197	 */
198	const INTENTIONALLY_PUBLIC = new Set(["register", "login", "logout"]);
199	
200	test("every exported server action identifies its caller inside the function", () => {
201	  const unguarded: string[] = [];
202	  for (const file of ACTION_FILES) {
203	    const src = source(file);
204	    assert.ok(src.includes('"use server"'), `${file} should declare "use server"`);
205	    for (const name of exportedActions(src)) {
