1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import { walletSplit, STRIPE_MIN_CENTS } from "../lib/wallet-split.ts";
4	
5	/**
6	 * `walletSplit` is the one function that decides how much of a purchase comes out
7	 * of the wallet and how much goes to the card. It is shared by the client wizards
8	 * (DeployWizard, ResizePicker, AddStorage) and the server actions (payAndDeploy,
9	 * resizeServer, expandDisk) and by renewals (worker/billing.ts), precisely so the
10	 * split a customer SEES is the split that gets CHARGED — the invariant the
11	 * $8.99/$6.29 incident broke elsewhere.
12	 *
13	 * The three properties that matter, because breaking any of them either loses
14	 * money or hands Stripe a charge it will reject:
15	 *   1. walletApplied + cardCents === dueCents, always, exactly (integer cents).
16	 *   2. cardCents is 0 or >= Stripe's 50c floor — no exemptions, for every input.
17	 *   3. nothing is ever negative, and the wallet is never over-drawn (except in the
18	 *      one explicitly flagged `belowStripeMin` case, where the wallet is the only
19	 *      leg that can settle the charge and the caller's guarded debit is the gate).
20	 */
21	
22	/** Amounts chosen to straddle every branch: zero, sub-floor, floor, real prices. */
23	const DUES = [0, 1, 25, 49, 50, 51, 99, 100, 149, 499, 500, 629, 899, 1299, 4999, 66508];
24	const BALANCES = [0, 1, 25, 49, 50, 51, 99, 100, 499, 628, 629, 900, 5000, 100000];
25	
26	test("wallet + card always sums to exactly the amount due", () => {
27	  for (const dueCents of DUES) {
28	    for (const balanceCents of BALANCES) {
29	      for (const useWallet of [true, false]) {
30	        const s = walletSplit({ dueCents, balanceCents, useWallet });
31	        assert.equal(
32	          s.walletApplied + s.cardCents,
33	          dueCents,
34	          `due ${dueCents}, balance ${balanceCents}, useWallet ${useWallet}`,
35	        );
36	      }
37	    }
38	  }
39	});
40	
41	test("the card leg is never below Stripe's 50c floor unless it is zero", () => {
42	  // A TOTAL property with no exemptions, which is the whole point. `cardCents` is
43	  // handed straight to createResizeCheckout / createDiskExpandCheckout by
44	  // lib/actions-server.ts and lib/actions-disk.ts, and those guard only
45	  // `cardCents <= 0` — so anything between 1c and 49c reaches Stripe and throws.
