import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { classifyCheckoutSession, isPurchaseLegSession } from "../lib/stripe.ts";

/**
 * The domain-registration card-payment path (Part 3 of the domain-wizard work).
 *
 * Domain registration has a pricing wrinkle none of the other order kinds have:
 * the retail/cost figures come from a LIVE registrar call (`checkDomains`), not
 * a DB-stored plan price, so "never re-quote after the card is charged" (the H2
 * incident documented on `OrderPrice` in lib/order.ts) matters here as much as
 * it does for VPS — a registrar's price can legitimately move between "customer
 * clicked Register" and "card cleared" exactly as a promo rotation can for a
 * VPS order. These tests pin that the price is FROZEN at checkout-session-
 * creation time and never re-derived at fulfilment, and that the wallet/card
 * split uses the platform's one shared floor-aware split function rather than a
 * bespoke subtraction that could hand Stripe a sub-50c charge.
 */

function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

/** The shape `classifyCheckoutSession` reads — metadata plus payment status. */
function session(metadata: Record<string, string> | null, paid = true) {
  return { metadata, payment_status: (paid ? "paid" : "unpaid") as "paid" | "unpaid" };
}

/* ------------------------------------------------------------------ *
 * classifyCheckoutSession — the domainOrder branch
 * ------------------------------------------------------------------ */

test("a domain-order session carries its DomainOrderIntent reference and the FROZEN per-year price", () => {
  const p = classifyCheckoutSession(
    session({
      nxeonUserId: "u1",
      nxeonDomainOrder: JSON.stringify({ domainOrderId: "doi_123" }),
      nxeonDomainOrderPrice: JSON.stringify({ priceCents: 1099, costCents: 800 }),
    }),
  );
  assert.equal(p.kind, "domainOrder");
  assert.equal(p.kind === "domainOrder" && p.userId, "u1");
  assert.equal(p.kind === "domainOrder" && p.domainOrderId, "doi_123");
  assert.deepEqual(p.kind === "domainOrder" ? p.sold : null, { priceCents: 1099, costCents: 800 });
});

test("a domain-order session with no stamped price still fulfils — sold is null, the DomainOrderIntent row is authoritative", () => {
  const p = classifyCheckoutSession(
    session({ nxeonUserId: "u1", nxeonDomainOrder: JSON.stringify({ domainOrderId: "doi_123" }) }),
  );
  assert.equal(p.kind, "domainOrder");
  assert.equal(p.kind === "domainOrder" && p.sold, null);
});

test("a malformed price mirror never turns a domain order into 'unreadable' — the DB row, not this metadata, is what gets charged", () => {
  // Unlike an order/resize/diskExpand session (where the price IS the only copy
  // of what to charge, so a broken stamp must refuse loudly), a domain order's
  // real price+contact live in the DomainOrderIntent row; nxeonDomainOrderPrice
  // is a metadata-only mirror kept for parity with the other order kinds'
  // naming convention. A bad mirror must degrade to `sold: null`, never refuse
  // the whole session — `placeDomainCardOrder` never reads `purpose.sold` to
  // decide what to charge.
  for (const bad of ['{"priceCents":"1099"}', "not json", '{"priceCents":1099}']) {
    const p = classifyCheckoutSession(
      session({ nxeonUserId: "u1", nxeonDomainOrder: '{"domainOrderId":"doi_1"}', nxeonDomainOrderPrice: bad }),
    );
    assert.equal(p.kind, "domainOrder", `price mirror ${bad} must not break classification`);
    assert.equal(p.kind === "domainOrder" && p.sold, null);
  }
});

test("a domain-order payload missing its DomainOrderIntent reference is UNREADABLE, never a top-up", () => {
  // Same incident class as order/resize/diskExpand (test/checkout-fulfilment.test.ts):
  // without domainOrderId there is nothing for placeDomainCardOrder to look up, and
  // that must never fall through to "no purchase metadata" — a card charge with no
  // registration and no failure row.
  for (const raw of ['{"planId":"p1"}', "null", "7", '"x"']) {
    const p = classifyCheckoutSession(session({ nxeonUserId: "u1", nxeonDomainOrder: raw }));
    assert.equal(p.kind, "unreadable", `nxeonDomainOrder ${raw} must be refused`);
    assert.equal(p.kind === "unreadable" && p.userId, "u1");
    assert.match(p.kind === "unreadable" ? p.detail : "", /nxeonDomainOrder/);
  }
});

test("truncated domain-order JSON is UNREADABLE, never a top-up", () => {
  const p = classifyCheckoutSession(session({ nxeonUserId: "u1", nxeonDomainOrder: '{"domainOrderId":"doi_' }));
  assert.equal(p.kind, "unreadable");
});

test("a domain order funds no other purchase kind and vice versa", () => {
  const p = classifyCheckoutSession(
    session({
      nxeonUserId: "u1",
      nxeonOrder: JSON.stringify({ planId: "p1" }),
      nxeonDomainOrder: JSON.stringify({ domainOrderId: "doi_1" }),
    }),
  );
  // nxeonOrder is checked first in classifyCheckoutSession, so a session that
  // (incorrectly) carried both keys resolves as the VPS order — documents the
  // precedence rather than silently picking one at random.
  assert.equal(p.kind, "order");
});

test("isPurchaseLegSession recognises a domain order as a funding leg, not a top-up", () => {
  assert.equal(isPurchaseLegSession({ nxeonDomainOrder: '{"domainOrderId":"doi_1"}' }), true);
  assert.equal(isPurchaseLegSession({}), false);
  assert.equal(isPurchaseLegSession(null), false);
});

/* ------------------------------------------------------------------ *
 * Frozen price — never re-quoted at fulfilment
 * ------------------------------------------------------------------ */

const ACTIONS_DOMAINS = code("../lib/actions-domains.ts");
const STRIPE = code("../lib/stripe.ts");
const FULFIL = code("../lib/fulfil-checkout.ts");

test("registerDomainCore is priced ONLY from its `priced` parameter — it never re-quotes the registrar", () => {
  // The core is the ONE place both the wallet path and the card-fulfilment path
  // charge a domain, so if IT re-quoted, both paths would inherit the H2-shaped
  // bug: a registrar price that moved between "customer clicked Register" (or
  // "card cleared") and this function running would silently change what's
  // charged. `checkDomains` is legitimately called elsewhere in this file (the
  // ONE live quote purchaseDomain takes before either branch, and the
  // refund-safety verifyRegistration check) — neither belongs inside the core.
  const start = ACTIONS_DOMAINS.indexOf("async function registerDomainCore(");
  assert.ok(start >= 0, "expected to find registerDomainCore");
  // registerDomainCore is the last top-level function before purchaseDomain —
  // slice to that boundary rather than brace-matching, since the body contains
  // template literals with `${…}` that a naive brace count would mishandle.
  const end = ACTIONS_DOMAINS.indexOf("export async function purchaseDomain(", start);
  assert.ok(end > start, "expected purchaseDomain to follow registerDomainCore");
  const body = ACTIONS_DOMAINS.slice(start, end);
  assert.ok(!/checkDomains\(/.test(body), "registerDomainCore must not call checkDomains — its price is a parameter");
  assert.match(body, /priced\.priceCents/, "the retail price charged comes from the `priced` parameter");
  assert.match(body, /priced\.costCents/, "the registrar cost charged comes from the `priced` parameter");
  assert.match(
    body,
    /domainTermPriceCents\(priced\.priceCents, dTerm\.years\)/,
    "the term total is derived from the frozen per-year price, not a fresh one",
  );
});

test("the card-shortfall branch stashes the live quote BEFORE opening the Stripe session, and passes that same object through", () => {
  // The DomainOrderIntent row and the Stripe session are both created from ONE
  // `checkDomains` result (priceCents/costCents resolved once, above) — never two
  // independent quotes that could disagree with each other.
  const start = ACTIONS_DOMAINS.indexOf("if (cardCents > 0) {");
  const end = ACTIONS_DOMAINS.indexOf("// Wallet covers it", start);
  assert.ok(start >= 0 && end > start, "expected the card-shortfall branch in purchaseDomain");
  const body = ACTIONS_DOMAINS.slice(start, end);
  assert.ok(!/checkDomains\(/.test(body), "the card-shortfall branch must not take a second, independent quote");
  assert.match(body, /priceCents,\s*$/m, "the DomainOrderIntent row is stashed with the already-fetched priceCents");
  assert.match(
    body,
    /createDomainOrderPaymentSession\(user, cardCents, domain, dTerm\.years, stashed\.id, priced\)/,
    "the SAME `priced` object stashed in the DB row is what the Stripe session is opened with",
  );
});

test("placeDomainCardOrder reads price and contact from the DomainOrderIntent row, never from Stripe metadata's `sold`", () => {
  const start = ACTIONS_DOMAINS.indexOf("export async function placeDomainCardOrder(");
  assert.ok(start >= 0);
  const body = ACTIONS_DOMAINS.slice(start);
  assert.match(body, /priceCents:\s*stashed\.priceCents,\s*costCents:\s*stashed\.costCents/, "priced from the row");
  assert.ok(
    !/purpose\.sold/.test(body),
    "placeDomainCardOrder must never charge off purpose.sold — the row is the single source of truth",
  );
});

test("createDomainOrderPaymentSession refuses rather than charges more than the frozen total", () => {
  const start = STRIPE.indexOf("export async function createDomainOrderPaymentSession(");
  assert.ok(start >= 0);
  const end = STRIPE.indexOf("export async function createTopUpPaymentSession(", start);
  const body = STRIPE.slice(start, end);
  assert.match(
    body,
    /orderTotalCents\s*=\s*domainTermPriceCents\(sold\.priceCents,\s*years\)/,
    "the refusal check is computed from the SOLD (frozen) price, not a fresh one",
  );
  assert.match(body, /if \(orderTotalCents < amountCents\)/, "and it actually refuses when the card leg would exceed it");
});

/* ------------------------------------------------------------------ *
 * Wallet + card split — same shared function every other order kind uses
 * ------------------------------------------------------------------ */

test("purchaseDomain computes the card leg with the shared walletSplit, not a bespoke subtraction", () => {
  // A naive `totalCents - user.balanceCents` can land a 1–49c remainder on the
  // card, which Stripe rejects outright (see lib/wallet-split.ts's own doc
  // comment on the incident this exact shape caused for VPS/disk-expand). Every
  // other card-funded purchase on this platform routes through `walletSplit`;
  // this pins that the domain path does too.
  assert.match(
    ACTIONS_DOMAINS,
    /walletSplit\(\{\s*dueCents:\s*totalCents,\s*balanceCents:\s*user\.balanceCents,\s*useWallet:\s*true\s*\}\)/,
    "purchaseDomain must split via walletSplit, floor-aware, like every other order kind",
  );
  assert.ok(
    !/totalCents\s*-\s*user\.balanceCents/.test(ACTIONS_DOMAINS),
    "no bespoke totalCents-minus-balance subtraction should survive alongside walletSplit",
  );
});

test("createDomainOrderPaymentSession is wired exactly like every other purchase-funding checkout session", () => {
  // Same regression this codebase already guards for order/game/host/email/
  // resize/diskExpand (test/checkout-metadata.test.ts's MONEY_CHECKOUT_FNS): a
  // session that can fund a real purchase must attach a Stripe CUSTOMER and ask
  // for `setup_future_usage`, or the card clears once and is never seen again
  // for the renewal sweep (the 2026-08-20 incident documented there).
  const start = STRIPE.indexOf("export async function createDomainOrderPaymentSession(");
  assert.ok(start >= 0);
  const end = STRIPE.indexOf("export async function createTopUpPaymentSession(", start);
  const body = STRIPE.slice(start, end);
  assert.match(body, /customer:\s*customerId/);
  assert.match(body, /payment_intent_data:\s*\{\s*setup_future_usage:\s*"off_session"\s*\}/);
  assert.doesNotMatch(body, /customer_email:/);
  assert.match(body, /ensureStripeCustomer\(user\)/);
  assert.match(body, /nxeonDomainOrder:\s*packMetadata\(/, "the intent reference is packed, not JSON.stringify'd inline");
  assert.match(body, /nxeonDomainOrderPrice:\s*packMetadata\(/, "the price mirror is packed too");
});

/* ------------------------------------------------------------------ *
 * Fulfilment dispatch shape
 * ------------------------------------------------------------------ */

test("the domainOrder branch claims, settles and dispatches exactly like every other fulfilled kind", () => {
  const branch = FULFIL.slice(FULFIL.indexOf('const domainOrder = purpose.kind === "domainOrder"'));
  assert.match(branch, /claim\(sessionId, "domainOrder"\)/);
  assert.match(branch, /placeDomainCardOrder\(sessionId\)/);
  assert.match(branch, /settle\(sessionId, "DONE"/);
  assert.match(branch, /settle\(sessionId, "FAILED"/);
  assert.match(branch, /notifyStalled\(/);
  assert.match(branch, /reportPurchase\(/, "a successful domain purchase reports the ad conversion like every other kind");
});

test("only an 'active' outcome is reported as fulfilled — refunded/needs-review are not silently claimed as success", () => {
  const branch = FULFIL.slice(
    FULFIL.indexOf('const domainOrder = purpose.kind === "domainOrder"'),
    FULFIL.indexOf("const resize = purpose.kind"),
  );
  assert.match(branch, /res\.kind === "active"/);
  assert.match(branch, /fulfilled:\s*true,\s*kind:\s*"domainOrder"/);
  // The non-active path must still be reachable and must return fulfilled:false —
  // both refunded (money safely back in the wallet) and needs-review (money kept,
  // flagged, never auto-refunded) count as "not a completed registration".
  assert.match(branch, /fulfilled:\s*false,\s*kind:\s*"domainOrder"/);
});

